window.ATLAS = {"destinations":[{"id":"kolkata","name":"Kolkata","region":"East","aliases":["Kolkata"],"air":"Netaji Subhash Chandra Bose International Airport (CCU)","rail":"Howrah Junction (HWH)","stay":"3–4 nights","plan":"Allow two festival outings and a separate museum day. Choose your neighbourhood around the programmes you want to attend.","nearby":["Victoria Memorial","Indian Museum"],"access":"Ask pandal organisers about step-free entrances, quieter visiting hours and the distance from the permitted vehicle drop-off.","checked":"2026-10-13","sources":[["Official destination and transport guide","https://www.incredibleindia.gov.in/en/west-bengal/kolkata"]]},{"id":"mysuru","name":"Mysuru","region":"South","aliases":["Mysuru"],"air":"Mysuru Airport (MYQ)","rail":"Mysuru Junction (MYS)","stay":"2–3 nights","plan":"Keep one day for the palace and another for the festival programme; add time if attending more than one major event.","nearby":["Mysuru Palace","Jaganmohan Palace art gallery"],"access":"Ask about accessible seating and the entry route for your particular Dasara event; palace access does not establish procession access.","checked":"2026-10-13","sources":[["Official destination and transport guide","https://www.incredibleindia.gov.in/en/karnataka/mysuru"]]},{"id":"varanasi","name":"Varanasi","region":"North","aliases":["Varanasi"],"air":"Lal Bahadur Shastri International Airport (VNS)","rail":"Varanasi Junction (BSB)","stay":"3 nights","plan":"Keep the festival evening free and visit Sarnath on another day. Arrange a meeting point and return transfer in advance.","nearby":["Sarnath","Assi Ghat"],"access":"Ask for a route without ghat steps, the closest permitted drop-off and accessible toilets. Confirm boarding assistance before arranging a boat.","checked":"2026-10-13","sources":[["Official destination and transport guide","https://www.incredibleindia.gov.in/en/uttar-pradesh/varanasi"],["District transport guide","https://varanasi.nic.in/how-to-reach/"]]},{"id":"jaipur","name":"Jaipur","region":"North","aliases":["Jaipur"],"air":"Jaipur International Airport (JAI)","rail":"Jaipur Junction (JP)","stay":"3 nights","plan":"Combine one festival day with two shorter sightseeing days; keep the event route separate from your sightseeing plan.","nearby":["Hawa Mahal","Jantar Mantar"],"access":"Ask each monument about lift or ramp access and which floors can be visited; confirm a suitable viewing area for processions.","checked":"2026-10-13","sources":[["Official destination and transport guide","https://www.incredibleindia.gov.in/en/rajasthan/jaipur"]]},{"id":"ahmedabad","name":"Ahmedabad","region":"West","aliases":["Ahmedabad"],"air":"Sardar Vallabhbhai Patel International Airport (AMD)","rail":"Ahmedabad Junction (ADI)","stay":"2–3 nights","plan":"Reserve time for the booked festival programme and a separate heritage visit. Confirm the actual venue rather than assuming all events use the riverfront.","nearby":["Sabarmati Gandhi Ashram","Sabarmati Riverfront"],"access":"Ask the chosen garba or kite venue about step-free entry, seating, toilets and quieter sessions; rooftop access needs a separate check.","checked":"2026-10-13","sources":[["Official destination and transport guide","https://www.incredibleindia.gov.in/en/gujarat/ahmedabad"]]},{"id":"mumbai","name":"Mumbai","region":"West","aliases":["Mumbai"],"air":"Chhatrapati Shivaji Maharaj International Airport (BOM)","rail":"Mumbai Central (MMCT); choose the station shown on your train booking","stay":"3–4 nights","plan":"Choose a compact area for each day and allow a separate outing for the festival. Keep return arrangements flexible around the announced event route.","nearby":["Gateway of India","National Gallery of Modern Art"],"access":"Ask the event organiser about crowd-managed access and drop-off points. Confirm station lifts and assistance for the exact journey you plan.","checked":"2026-10-13","sources":[["Official destination and transport guide","https://www.incredibleindia.gov.in/en/maharashtra/mumbai"]]},{"id":"kochi","name":"Kochi","region":"South","aliases":["Kochi"],"air":"Cochin International Airport (COK)","rail":"Ernakulam Junction (ERS)","stay":"2–3 nights","plan":"Combine a confirmed Onam programme with a separate day in Fort Kochi and Mattancherry. Reserve any hosted meal directly.","nearby":["Fort Kochi","Mattancherry Palace"],"access":"If using a ferry, ask about boarding gradients and assistance at both jetties. Check step-free access to the selected meal or performance venue.","checked":"2026-10-13","sources":[["Official destination and transport guide","https://www.incredibleindia.gov.in/en/kerala/kochi"],["Fort Kochi and nearby heritage","https://ernakulam.nic.in/en/tourist-place/fort-kochi/"]]},{"id":"udaipur","name":"Udaipur","region":"North","aliases":["Udaipur"],"air":"Maharana Pratap Airport (UDR)","rail":"Udaipur City (UDZ)","stay":"2–3 nights","plan":"Keep the festival programme and a palace visit on separate days; leave a spare half-day for changes to local arrangements.","nearby":["City Palace","Lake Pichola"],"access":"Ask which palace areas can be reached without stairs and whether a step-free festival viewing point is available. Confirm boat boarding separately.","checked":"2026-10-13","sources":[["Official destination and transport guide","https://www.incredibleindia.gov.in/en/rajasthan/udaipur"]]},{"id":"amritsar","name":"Amritsar","region":"North","aliases":["Amritsar"],"air":"Sri Guru Ram Dass Jee International Airport (ATQ)","rail":"Amritsar Junction (ASR)","stay":"2–3 nights","plan":"Allow time for the religious observance and a separate history-focused outing. Confirm the particular community programme before choosing dates.","nearby":["Jallianwala Bagh","Partition Museum"],"access":"Ask the gurdwara or event host about wheelchair routes, resting places and assistance with entry procedures; check museum access separately.","checked":"2026-10-13","sources":[["Official destination and transport guide","https://www.incredibleindia.gov.in/en/punjab/amritsar"]]},{"id":"hyderabad","name":"Hyderabad","region":"South","aliases":["Hyderabad"],"air":"Rajiv Gandhi International Airport (HYD)","rail":"Hyderabad Deccan / Nampally (HYB); verify your booked station","stay":"3 nights","plan":"Keep one outing for the festival and another for the old-city sights. Confirm where the specific Bathukamma or Bonalu programme takes place.","nearby":["Charminar","Salar Jung Museum"],"access":"Ask about accessible viewing areas, shade, toilets and transport drop-off points for the specific procession or gathering.","checked":"2026-10-13","sources":[["Official destination and transport guide","https://www.incredibleindia.gov.in/en/telangana/hyderabad"]]},{"id":"guwahati","name":"Guwahati","region":"North East","aliases":["Guwahati"],"air":"Lokpriya Gopinath Bordoloi International Airport (GAU)","rail":"Guwahati Railway Station (GHY)","stay":"2–3 nights","plan":"Plan around a confirmed Bihu programme and allow a separate day for city sights. This base does not cover the whole of Assam.","nearby":["Assam State Museum","Kamakhya Temple"],"access":"Ask the performance venue about seating and step-free entry. Confirm temple access and queue assistance directly rather than assuming it matches the concert venue.","checked":"2026-10-13","sources":[["Official destination and transport guide","https://www.incredibleindia.gov.in/en/assam/guwahati"]]},{"id":"khajuraho","name":"Khajuraho","region":"Central","aliases":["Khajuraho"],"air":"Khajuraho Airport (HJR)","rail":"Khajuraho Railway Station (KURJ)","stay":"2–3 nights","plan":"Pair one or two evening performances with daytime temple visits. Check the published running order before booking your stay.","nearby":["Western Group of Temples","Lakshmana Temple"],"access":"Ask about step-free routes, accessible toilets and reserved seating at the actual performance site; temple steps may require an alternative viewing plan.","checked":"2026-10-13","sources":[["Official destination and transport guide","https://www.incredibleindia.gov.in/en/madhya-pradesh/khajuraho"]]},{"id":"mathura","name":"Mathura and Vrindavan","region":"North","aliases":["Mathura","Vrindavan"],"air":"Delhi Indira Gandhi International Airport (DEL) is a regional arrival option; onward travel is required","rail":"Mathura Junction (MTJ)","stay":"3–4 nights","plan":"Choose the exact local Holi events first, then build transfer and rest time around them. Do not try to cover every Braj town in one day.","nearby":["Government Museum, Mathura","Vishram Ghat"],"access":"Ask the chosen temple or host about crowd controls, step-free entry, toilets and a quiet exit route. Confirm the last accessible vehicle drop-off.","checked":"2026-10-13","sources":[["Official destination and transport guide","https://www.incredibleindia.gov.in/en/uttar-pradesh/mathura"]]},{"id":"pushkar","name":"Pushkar","region":"North","aliases":["Pushkar"],"air":"Jaipur International Airport (JAI) is a regional gateway; onward travel is required","rail":"Ajmer railway station for onward travel to Pushkar","stay":"2–3 nights","plan":"Choose the fair activities you want to see and allow time for the town and lake. Check the final programme before fixing your stay.","nearby":["Pushkar Lake","Brahma Temple"],"access":"Ask about firm-surface routes at the fair, seating and accessible toilets. Confirm a route that avoids lake steps if required.","checked":"2026-10-13","sources":[["Official destination and transport guide","https://www.tourism.rajasthan.gov.in/pushkar.html"]]},{"id":"puri","name":"Puri","region":"East","aliases":["Puri"],"air":"Biju Patnaik International Airport (BBI), Bhubaneswar","rail":"Puri Railway Station (PURI)","stay":"3 nights","plan":"Keep the main festival day free and consider Konark on another day. Confirm event access and entry rules before making plans.","nearby":["Konark Sun Temple (separate excursion)","Puri seafront"],"access":"Ask organisers for accessible viewing arrangements, toilets and drop-off points. Confirm temple entry rules and do not assume attendance at a public procession includes temple admission.","checked":"2026-10-13","sources":[["Official destination and transport guide","https://www.incredibleindia.gov.in/en/odisha/puri"],["District transport guide — Puri rail terminus","https://puri.odisha.gov.in/en/tourism/how-to-reach"]]},{"id":"kisama","name":"Kohima and Kisama","region":"North East","aliases":["Kisama Heritage Village"],"air":"Dimapur Airport; onward road travel to Kohima and Kisama","rail":"Dimapur railway station; onward road travel required","stay":"3–4 nights","plan":"Allow an arrival and transfer day, one or two festival days, and time in Kohima. Confirm road transfers and visitor requirements with official tourism services.","nearby":["Kohima War Cemetery","Kisama Heritage Village"],"access":"Ask the festival team about gradients, firm paths, accessible toilets and seating near the programme. Confirm vehicle access to your accommodation and the venue.","checked":"2026-10-13","sources":[["Official destination and transport guide","https://kohima.nic.in/how-to-reach/"],["Kisama visitor information","https://kohima.nic.in/tourist-place/kisama-heritage-village/"],["Kohima places of interest","https://kohima.nic.in/places-of-interest/"]]}],"states":[{"code":"AP","name":"Andhra Pradesh","region":"South","type":"State"},{"code":"AR","name":"Arunachal Pradesh","region":"Northeast","type":"State"},{"code":"AS","name":"Assam","region":"Northeast","type":"State"},{"code":"BR","name":"Bihar","region":"East","type":"State"},{"code":"CT","name":"Chhattisgarh","region":"Central","type":"State"},{"code":"GA","name":"Goa","region":"West","type":"State"},{"code":"GJ","name":"Gujarat","region":"West","type":"State"},{"code":"HR","name":"Haryana","region":"North","type":"State"},{"code":"HP","name":"Himachal Pradesh","region":"North","type":"State"},{"code":"JH","name":"Jharkhand","region":"East","type":"State"},{"code":"KA","name":"Karnataka","region":"South","type":"State"},{"code":"KL","name":"Kerala","region":"South","type":"State"},{"code":"MP","name":"Madhya Pradesh","region":"Central","type":"State"},{"code":"MH","name":"Maharashtra","region":"West","type":"State"},{"code":"MN","name":"Manipur","region":"Northeast","type":"State"},{"code":"ML","name":"Meghalaya","region":"Northeast","type":"State"},{"code":"MZ","name":"Mizoram","region":"Northeast","type":"State"},{"code":"NL","name":"Nagaland","region":"Northeast","type":"State"},{"code":"OR","name":"Odisha","region":"East","type":"State"},{"code":"PB","name":"Punjab","region":"North","type":"State"},{"code":"RJ","name":"Rajasthan","region":"West","type":"State"},{"code":"SK","name":"Sikkim","region":"Northeast","type":"State"},{"code":"TN","name":"Tamil Nadu","region":"South","type":"State"},{"code":"TG","name":"Telangana","region":"South","type":"State"},{"code":"TR","name":"Tripura","region":"Northeast","type":"State"},{"code":"UP","name":"Uttar Pradesh","region":"North","type":"State"},{"code":"UT","name":"Uttarakhand","region":"North","type":"State"},{"code":"WB","name":"West Bengal","region":"East","type":"State"},{"code":"AN","name":"Andaman and Nicobar Islands","region":"Islands","type":"Union territory"},{"code":"CH","name":"Chandigarh","region":"North","type":"Union territory"},{"code":"DH","name":"Dadra and Nagar Haveli and Daman and Diu","region":"West","type":"Union territory"},{"code":"DL","name":"Delhi","region":"North","type":"Union territory"},{"code":"JK","name":"Jammu and Kashmir","region":"North","type":"Union territory"},{"code":"LA","name":"Ladakh","region":"North","type":"Union territory"},{"code":"LD","name":"Lakshadweep","region":"Islands","type":"Union territory"},{"code":"PY","name":"Puducherry","region":"South","type":"Union territory"}],"festivals":[{"name":"Ugadi","season":"March–April","months":[3,4],"theme":"Telugu New Year","place":"Vijayawada & Tirupati","description":"Homes are decorated with mango leaves and families share ugadi pachadi, whose contrasting flavours symbolise the experiences of life.","id":"ugadi","states":["AP","KA","TG"],"regions":["South"],"locations":[{"state":"AP","text":"Vijayawada & Tirupati"},{"state":"KA","text":"Across Karnataka"}],"native":"ఉగాది / ಯುಗಾದಿ","categories":["Community","Devotion"],"story":"Ugadi welcomes the New Year in Telugu and Kannada traditions at the beginning of Chaitra. It is a time for fresh beginnings, spring produce and family visits. Practices differ between Andhra Pradesh, Telangana and Karnataka: a shared calendar occasion does not mean an identical meal or ceremony everywhere. Household observances are central, while temples and community associations may organise programmes that visitors can attend.","rituals":["Decorating entrances and making floor designs","Prayers and listening to the new year’s almanac where locally observed","Sharing foods that combine contrasting tastes"],"food":"Ugadi pachadi in Telugu households and neem with jaggery in Karnataka express life’s contrasting experiences. Festive sweets vary by region and family.","dress":"Saris, kurtas and other festive clothes are common. Follow the dress guidance of any temple you visit.","tips":["Ask your host which local customs they follow; avoid treating one regional tradition as universal.","Arrange a community visit in advance, since a public holiday does not imply open access to homes."],"places":[["Bengaluru","KA",77.59,12.97,"A base for Kannada Ugadi observances; confirm individual temple and community programmes."]],"sources":[["Karnataka Tourism: Ugadi","https://karnatakatourism.org/en/blogs/best-places-to-experince-ugadi-in-karnataka-and-must-try-sweets"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Sankranti","season":"January","months":[1],"theme":"Harvest","place":"Across the state","description":"Rangoli, decorated cattle and family gatherings mark the harvest season.","id":"sankranti","states":["AP"],"regions":["South"],"locations":[{"state":"AP","text":"Across the state"}],"native":"సంక్రాంతి","categories":["Harvest","Community"],"story":"This guide focuses on Andhra Pradesh’s Sankranti season, when farming families mark the harvest and welcome relatives home. The celebration unfolds across days with distinct names and customs, including Bhogi and Kanuma. The Godavari region is particularly associated with these gatherings. Related midwinter festivals elsewhere in India have their own identities; the Andhra programme should not be assumed to match those of Gujarat or Tamil Nadu.","rituals":["Bhogi gatherings at the beginning of the festive period","Decorative muggu floor patterns outside homes","Kanuma observances recognising cattle and agricultural life"],"food":"Families prepare regional sweets and celebratory meals. Ask what is being served locally instead of expecting a fixed statewide menu.","dress":"Festive saris and traditional clothing are common, alongside everyday dress. Wear practical shoes for village paths.","tips":["Choose a hosted village experience or announced public programme; private courtyards are not visitor attractions.","Check the date and location of each day’s activity separately, allowing time for holiday traffic."],"places":[["Amalapuram","AP",82,16.58,"Gateway to Konaseema celebrations; town-centre marker, not a specific event entrance."]],"sources":[["Konaseema district: Festivals","https://konaseema.ap.gov.in/festivals/"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Dree","season":"July","months":[7],"theme":"Harvest","place":"Ziro Valley","description":"The Apatani community gathers for agricultural rituals, songs and dances, offering prayers for a healthy crop.","id":"dree","states":["AR"],"regions":["Northeast"],"locations":[{"state":"AR","text":"Ziro Valley"}],"native":"","categories":["Harvest","Community","Devotion"],"story":"Dree belongs to the Apatani community of Arunachal Pradesh’s Ziro Valley. Its meaning is closely connected to wet-rice cultivation and the wellbeing of people, crops and livestock. Ceremonies seek protection from pests and illness and blessings for fertile fields. Understanding this agricultural relationship helps visitors see Dree as a living community observance, rather than simply a stage performance. Public celebrations and village rites may offer different levels of access.","rituals":["Prayers connected with crop protection and wellbeing","Community gatherings during the agricultural festival","Public cultural presentations where announced"],"food":"Food is shared according to the host community’s arrangements. Ask about ingredients and whether a meal is an invitation or a commercial service.","dress":"Apatani textiles are part of community identity. Visitors can wear comfortable clothing without imitating ceremonial dress.","tips":["Use a local host to understand which ceremonies welcome visitors and which are private.","Ask before photographing rituals or people, and keep to paths around working rice fields."],"places":[["Ziro","AR",93.83,27.59,"Base for Apatani communities in Ziro Valley; confirm the specific celebration ground."]],"sources":[["Lower Subansiri district: Dree Festival","https://lowersubansiri.nic.in/festivals/"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Losar","season":"February–March","months":[2,3],"theme":"New Year","place":"Tawang & West Kameng","description":"Monpa communities welcome the new year with monastery prayers, family visits and traditional food.","id":"losar","states":["AR","SK"],"regions":["Northeast"],"locations":[{"state":"AR","text":"Tawang & West Kameng"},{"state":"SK","text":"Gangtok & monasteries"}],"native":"","categories":["Community","Devotion"],"story":"Losar is a New Year celebration within Tibetan Buddhist cultural traditions. In Tawang it is especially important to Monpa communities; it is also observed in Sikkim and other Himalayan regions. Religious prayers, family reunions and meals accompany hopes for a fortunate year. Local calendars and customs differ, so this guide does not assign one universal date or programme. Tawang’s Torgya monastery festival is a separate occasion and should not be confused with Losar.","rituals":["New Year prayers at home and religious venues","Visits and reunions with relatives","Sharing festive meals and greetings"],"food":"Traditional feasts form part of the celebration. Regional foods and household recipes differ; ask hosts what their dishes signify.","dress":"Wear modest layers for monastery visits. Community ceremonial clothing is meaningful rather than a required visitor costume.","tips":["Confirm the community’s own calendar before arranging travel, especially when comparing Himalayan destinations.","Ask separately about monastery access and household invitations; a family celebration may not offer a public performance."],"places":[["Tawang","AR",91.86,27.59,"Monpa cultural centre; visitor programmes and religious schedules vary."]],"sources":[["Tawang district: Culture and heritage","https://tawang.nic.in/tourism/culture-heritage/"],["Sikkim government: Buddhist festivals","https://www.sikkim.gov.in/departments/ecclesiastical-affairs-department/buddhist-festivals"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Bohag Bihu","season":"April","months":[4],"theme":"New Year & spring","place":"Guwahati & across Assam","description":"Also called Rongali Bihu, this spring celebration welcomes the Assamese New Year with Bihu dance, music and festive meals.","id":"bohag-bihu","states":["AS"],"regions":["Northeast"],"locations":[{"state":"AS","text":"Guwahati & across Assam"}],"native":"বহাগ বিহু","categories":["Harvest","Music & dance","Community"],"story":"Bohag, or Rongali, Bihu marks the Assamese New Year and the arrival of the agricultural spring. It is distinct from Magh Bihu after the harvest and Kati Bihu later in the farming cycle.","rituals":["Bihu songs and dancing","Husori group performances","Family visits and exchanges of gamosa cloths"],"food":"Pitha and laru are familiar festive foods; recipes differ between communities.","dress":"Mekhela chador and gamosa are associated with Assamese celebrations.","tips":["Seek a publicly advertised performance if you are visiting independently.","Ask before entering a household celebration."],"places":[["Guwahati","AS",91.74,26.14,"Public Bihu stages and cultural programmes."],["Dibrugarh","AS",94.91,27.47,"Regional community celebrations."]],"sources":[["Ministry of Tourism: Bohag Bihu","https://www.utsav.gov.in/view-event/bohag-bihu-or-rangali-bihu"]],"photo":{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/ce/Bihu_dance.jpg/960px-Bihu_dance.jpg","alt":"Bihu performers in red and cream clothing with drums, a horn and a decorated woven hat","caption":"Rongali Bihu performers in Assam, April 2018. Historical photograph.","author":"Diganta Talukdar","source":"https://commons.wikimedia.org/wiki/File:Bihu_dance.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},"reviewed":"2026-10-10","destinationIds":["guwahati"]},{"name":"Magh Bihu","season":"January","months":[1],"theme":"Harvest","place":"Across Assam","description":"Community feasts and ceremonial meji bonfires celebrate the end of the harvest season.","id":"magh-bihu","states":["AS"],"regions":["Northeast"],"locations":[{"state":"AS","text":"Across Assam"}],"native":"মাঘ বিহু","categories":["Harvest","Community"],"story":"Magh Bihu, also called Bhogali Bihu, celebrates the Assamese harvest season with an emphasis on food and community. Uruka, the preceding evening, is a time for shared meals. Temporary gathering structures and the meji bonfire are familiar features, although practices vary across Assam. It is distinct from springtime Bohag Bihu and the more restrained Kati Bihu: planning around the right Bihu matters if you want to understand its agricultural meaning.","rituals":["Uruka meals with family and neighbours","Building temporary gathering structures","Meji bonfire observances where locally practised"],"food":"Pitha is closely associated with the festival; preparations include different rice-based snacks and sweets. A host can explain local varieties and ingredients.","dress":"Assamese textiles may be worn at gatherings. Everyday respectful clothing is appropriate unless an organiser advises otherwise.","tips":["Arrange access through a host instead of assuming a village feast is open to every passer-by.","Observe bonfires from a safe distance and follow local organisers’ instructions around temporary structures."],"places":[["Jorhat","AS",94.22,26.75,"Town and surrounding communities; each Uruka gathering has its own arrangements."]],"sources":[["Ministry of Tourism: Bhogali Bihu","https://utsav.gov.in/public/view-event/bhogali-bihu-or-magh-bihu-1"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Chhath Puja","season":"October–November","months":[10,11],"theme":"Sun worship","place":"Patna river ghats","description":"Devotees offer prayers to the setting and rising sun at rivers and ponds, with fasting and carefully prepared offerings.","id":"chhath-puja","states":["BR","JH","UP","DL"],"regions":["East","North"],"locations":[{"state":"BR","text":"Patna river ghats"}],"native":"छठ पूजा","categories":["Devotion","Community"],"story":"Chhath is an observance of gratitude to the sun and Chhathi Maiya. It is especially associated with Bihar and neighbouring regions, and is also observed by communities far from their home states.","rituals":["Fasting and carefully prepared offerings","Prayers to the setting sun","Prayers at sunrise near water"],"food":"Thekua and fruit are among the offerings; preparation follows household religious practices.","dress":"Dress respectfully and keep worship areas clear.","tips":["Do not interrupt fasting devotees or step across offerings.","Stay behind waterside barriers; ask before close-up photographs."],"places":[["Patna","BR",85.14,25.61,"Designated river ghats; access arrangements change by year."]],"sources":[["Incredible India: Chhath Puja","https://www.incredibleindia.gov.in/en/festivals-and-events/chhath-puja"]],"photo":{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f7/CHHATH_PUJA.jpg/960px-CHHATH_PUJA.jpg","alt":"Devotees standing in the Hooghly River near Howrah Bridge with the sun low on the horizon","caption":"Chhath worship at the Hooghly River in Kolkata, 2022. Historical photograph.","author":"Susovan Chakraborty5","source":"https://commons.wikimedia.org/wiki/File:CHHATH_PUJA.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},"reviewed":"2026-10-10","destinationIds":[]},{"name":"Sonepur Mela","season":"November–December","months":[11,12],"theme":"Traditional fair","place":"Sonepur","description":"Around Kartik Purnima, pilgrims, performers and traders gather at this historic riverside fair.","id":"sonepur-mela","states":["BR"],"regions":["East"],"locations":[{"state":"BR","text":"Sonepur"}],"native":"सोनपुर मेला","categories":["Community","Arts","Devotion"],"story":"Sonepur Mela brings together pilgrimage, trade and cultural programmes near the confluence of the Ganga and Gandak in Bihar. Its opening is associated with Kartik Purnima, when devotees visit the rivers and Harihar Nath Temple. The fair is historically known for livestock trading, but visitors can also explore crafts, performances and the atmosphere of a large regional gathering. Historic descriptions of animal sales should not be treated as a current programme or an invitation to buy wildlife.","rituals":["Kartik Purnima pilgrimage and temple prayers","Browsing market stalls and regional crafts","Announced music and cultural performances"],"food":"Fairground vendors offer snacks and meals. Choose freshly prepared food and ask about ingredients; no single dish defines the whole mela.","dress":"Respectful everyday clothing and comfortable footwear suit the combination of religious visits and long walks.","tips":["Check the current fairground plan and performance schedule before visiting.","Use designated riverside routes and keep photography away from people bathing or worshipping."],"places":[["Sonepur","BR",85.18,25.7,"Town near the river confluence; current fair entrances must be checked locally."]],"sources":[["Bihar Tourism: Sonepur Mela","https://tourism.bihar.gov.in/en/experiences/festivals-and-fairs/fairs/sonepur-mela"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Bastar Dussehra","season":"August–October","months":[8,9,10],"theme":"Community & devotion","place":"Jagdalpur, Bastar","description":"A long cycle of rituals honours Goddess Danteshwari, bringing together local communities, ceremonial chariots and regional deities.","id":"bastar-dussehra","states":["CT"],"regions":["Central"],"locations":[{"state":"CT","text":"Jagdalpur, Bastar"}],"native":"बस्तर दशहरा","categories":["Devotion","Arts","Community"],"story":"Bastar Dussehra is a long cycle of observances centred on Danteshwari and the deity traditions of Bastar. Unlike many other Dussehra celebrations, it does not centre on burning an effigy of Ravana. Village deities and their representatives gather, while chariot-making connects skilled craft, faith and collective participation. The cycle extends far beyond the main procession days, so choosing a particular ritual is more useful than assuming there is one short festival weekend.","rituals":["Pat Jatra associated with wood for the chariot","Crafting the ceremonial wooden chariot","Gatherings of deities and chariot processions"],"food":"Explore regional food through public vendors or a local host. Ritual offerings and private community meals follow their own rules.","dress":"Dress respectfully and keep hands free in crowds. Community regalia and deity objects should never be handled without permission.","tips":["Choose authorised viewing areas and keep clear of chariot ropes and procession routes.","Ask a local guide to explain the specific stage you are seeing rather than applying another region’s Dussehra story."],"places":[["Jagdalpur","CT",82.02,19.07,"Main town associated with Bastar Dussehra; procession routes are programme-dependent."]],"sources":[["Incredible India: Bastar Dussehra","https://www.incredibleindia.gov.in/en/festivals-and-events/chhattisgarh/bastar-dussehra"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Hareli","season":"July–August","months":[7,8],"theme":"Agriculture","place":"Across Chhattisgarh","description":"Farming communities honour agricultural tools and celebrate the green season with local games and traditions.","id":"hareli","states":["CT"],"regions":["Central"],"locations":[{"state":"CT","text":"Across Chhattisgarh"}],"native":"हरेली","categories":["Harvest","Community"],"story":"Hareli is associated with the greenery of the monsoon and Chhattisgarh’s agricultural life. Village celebrations recognise the work of farming and the season’s hopes for growth. Gedi, the practice of walking on bamboo stilts, is a well-known cultural feature in parts of the state. On Hareli Amavasya, Bastar also observes Pat Jatra within its longer Dussehra cycle; that specific rite should be distinguished from the broader household and village festival.","rituals":["Respecting agricultural tools and farming work","Village gatherings marking the monsoon season","Gedi displays where locally organised"],"food":"Household and village meals vary. Ask your host about local preparations rather than expecting a standard festival menu.","dress":"Comfortable everyday clothing suits public gatherings. Village participants may use regional festive dress.","tips":["Confirm that a village gathering welcomes visitors and ask before entering farms or courtyards.","Watch stilt demonstrations from the space organisers provide; do not handle equipment without an invitation."],"places":[["Raipur","CT",81.63,21.25,"A planning base for announced cultural programmes and nearby village visits."]],"sources":[["Chhattisgarh district administration: Culture and heritage","https://mohla-manpur-ambagarhchowki.cg.gov.in/en/culture-heritage/"],["Ministry of Tourism: Bastar heritage trail and Pat Jatra","https://utsav.gov.in/view-event/bastar-dussehra-bastar-heritage-trail"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Carnival","season":"February–March","months":[2,3],"theme":"Street celebration","place":"Panaji, Margao & Vasco","description":"Colourful floats, music and dancing fill the streets in the days leading up to Lent.","id":"carnival","states":["GA"],"regions":["West"],"locations":[{"state":"GA","text":"Panaji, Margao & Vasco"}],"native":"Carnaval","categories":["Arts","Music & dance","Community"],"story":"Goa’s Carnival, often written Carnaval, is a public celebration with processions, music, costumes and decorated floats. Its history is linked to the pre-Lenten carnival tradition, with a distinctive Goan expression today. Parades in different towns form separate programmes rather than one continuously moving event. The figure of King Momo is associated with the festivities. Carnival is distinct from Shigmo, another major Goan celebration with its own seasonal and cultural roots.","rituals":["Decorated float parades","Music and dance along announced routes","Costume presentations and community entertainment"],"food":"Food vendors and nearby restaurants offer varied Goan dishes. Ask about seafood, meat and vegetarian ingredients rather than assuming a uniform carnival menu.","dress":"Costumes belong to participating groups; spectators can wear light, comfortable clothes and walking shoes.","tips":["Use the published town-by-town route and arrival information to choose a viewing point.","Respect barriers and give floats and performers room; arrange your return journey before road closures begin."],"places":[["Panaji","GA",73.83,15.49,"One of the parade cities; confirm the current route and viewing arrangements."]],"sources":[["Goa Tourism: Carnaval celebrations","https://goatourism.gov.in/blog-list/goa-carnaval-2026-concludes-on-a-grand-note-across-the-state-drawing-enthusiastic-crowds-global-attention/"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Shigmo","season":"March","months":[3],"theme":"Spring","place":"Across Goa","description":"Folk dances, processions and elaborate floats bring Goan spring traditions into public celebrations.","id":"shigmo","states":["GA"],"regions":["West"],"locations":[{"state":"GA","text":"Across Goa"}],"native":"शिगमो","categories":["Arts","Music & dance","Community"],"story":"Shigmo is a Goan spring celebration rooted in local community and religious traditions. Music, folk dance and processions carry these traditions into public space. Organised town parades include cultural presentations and floats, while village observances have their own character and timing. Shigmo is not another name for Carnival: learning which event is scheduled will help you understand the performances and avoid travelling for the wrong programme.","rituals":["Folk music and dance presentations","Community processions and local observances","Decorated floats at organised Shigmotsav parades"],"food":"Try regional food from public stalls or restaurants. Household festive dishes vary, and religious spaces may have their own food restrictions.","dress":"Performers wear costumes suited to their tradition. Visitors need comfortable clothing rather than ceremonial dress.","tips":["Check the parade schedule for the particular town you want to visit; dates differ across Goa.","Ask before close-up photographs and stay out of performance formations, especially when instruments or large floats are moving."],"places":[["Ponda","GA",74.01,15.4,"A base for Goan cultural traditions; confirm announced parade and village programmes."]],"sources":[["Goa Tourism: Faith and heritage celebrations","https://goatourism.gov.in/faith-heritage-and-spiritual-tourism-lead-goa-towards-a-more-reflective-tourism-experience/"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Navratri","season":"September–October","months":[9,10],"theme":"Dance & devotion","place":"Vadodara & Ahmedabad","description":"Nine nights of devotion to the goddess are celebrated with circular garba dancing and dandiya raas.","id":"navratri","states":["GJ","MH","RJ"],"regions":["West"],"locations":[{"state":"GJ","text":"Vadodara & Ahmedabad"}],"native":"નવરાત્રી","categories":["Devotion","Music & dance","Community"],"story":"Navratri honours the goddess over nine nights. Gujarat's garba circles and dandiya gatherings are especially well known, while other regions have distinct devotional and artistic traditions. This guide focuses on the autumn celebration.","rituals":["Garba and dandiya raas","Prayers and household observances","Community gatherings over successive evenings"],"food":"Fasting and festive menus differ. Ask hosts about the customs of the event you attend.","dress":"Chaniya cholis and kediyu outfits are associated with Gujarati celebrations; comfortable footwear and freedom of movement matter.","tips":["Join dancing only where visitors are welcome; follow the direction of the circle.","Check passes and entry rules for each venue."],"places":[["Ahmedabad","GJ",72.58,23.02,"Public and ticketed garba venues."],["Vadodara","GJ",73.18,22.31,"Large organised dance gatherings; passes vary."]],"sources":[["Incredible India: Navratri","https://www.incredibleindia.gov.in/en/festivals-and-events/navratri"]],"photo":{"url":"https://upload.wikimedia.org/wikipedia/commons/2/29/Navratri_Garba.jpg","alt":"Garba dancers in colourful embroidered clothing performing outdoors at night","caption":"Navratri garba in Ahmedabad. Historical photograph; capture date not supplied.","author":"Hardik jadeja","source":"https://commons.wikimedia.org/wiki/File:Navratri_Garba.jpg","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0/"},"reviewed":"2026-10-10","destinationIds":["ahmedabad"]},{"name":"Uttarayan","season":"January","months":[1],"theme":"Kite festival","place":"Ahmedabad","description":"Rooftops fill with kite flyers during Makar Sankranti, with festive food and colourful skies.","id":"uttarayan","states":["GJ"],"regions":["West"],"locations":[{"state":"GJ","text":"Ahmedabad"}],"native":"ઉત્તરાયણ","categories":["Community","Arts"],"story":"Uttarayan is closely associated with kite flying across Gujarat around Makar Sankranti. Rooftops and open grounds become social spaces where families and friends watch the sky and share food. Ahmedabad’s organised International Kite Festival adds a public showcase of imaginative kites and visiting flyers. That scheduled event is related to, but not identical with, everyday neighbourhood celebrations; its venue and dates need separate confirmation.","rituals":["Kite flying and watching from open spaces","Neighbourhood and family gatherings","Demonstrations at the organised International Kite Festival"],"food":"Seasonal food is part of gatherings, but menus vary by household. Ask a local host about their favourite winter dishes and dietary ingredients.","dress":"Wear comfortable clothes, sun protection and secure footwear. Rooftop access is not a reason to approach unprotected edges.","tips":["Choose a public viewing ground or an explicitly hosted rooftop visit.","Avoid hazardous kite string and never retrieve kites near traffic or power lines; follow local organiser guidance."],"places":[["Ahmedabad","GJ",72.58,23.02,"Public kite-festival programmes and neighbourhood celebrations; verify the current venue."]],"sources":[["Gujarat Tourism: International Kite Festival","https://gujarattourism.com/fair-and-festival/international-kite-festival.html"]],"reviewed":"2026-10-11","photo":null,"destinationIds":["ahmedabad"]},{"name":"Teej","season":"July–August","months":[7,8],"theme":"Monsoon","place":"Across Haryana","description":"Songs, swings and gatherings celebrate the arrival of the monsoon and the traditions of Teej.","id":"teej","states":["HR"],"regions":["North"],"locations":[{"state":"HR","text":"Across Haryana"}],"native":"तीज","categories":["Devotion","Community","Music & dance"],"story":"This guide focuses on Haryana’s monsoon Teej traditions. The festival connects devotion to Parvati and Shiva with family relationships and the relief brought by seasonal rain. Women’s gatherings, songs, dance, mehendi and swings are familiar expressions of the occasion. Teej is observed in several regions and includes differently named observances; a public celebration in Haryana need not share the ritual calendar or procession format of Jaipur.","rituals":["Women’s songs and dance gatherings","Mehendi and decorated swings","Prayers and family observances, including fasting for some participants"],"food":"Festive foods and sweets accompany social gatherings, while fasting practices vary. Ask hosts before offering food to someone observing a fast.","dress":"Colourful festive clothing and jewellery are common. Visitors can dress respectfully without copying personal or ceremonial adornment.","tips":["Ask before joining a women’s gathering or photographing participants at close range.","Check whether an advertised programme is a public cultural event or a private devotional observance."],"places":[["Rohtak","HR",76.61,28.9,"Haryana cultural setting; identify a publicly announced local celebration before travelling."]],"sources":[["Haryana Art and Cultural Affairs: Teej","https://artandculturalaffairshry.gov.in/teej-festival/"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Surajkund International Crafts Mela","season":"February","months":[2],"theme":"Crafts & culture","place":"Surajkund, Faridabad","description":"Artisans and performers gather for a major cultural fair showcasing handicrafts, folk traditions and regional food.","id":"surajkund-international-crafts-mela","states":["HR"],"regions":["North"],"locations":[{"state":"HR","text":"Surajkund, Faridabad"}],"native":"","categories":["Arts","Community","Music & dance"],"story":"Surajkund International Crafts Mela is an organised fair in Faridabad that brings craftspeople, weavers and performing groups together. Its central purpose is to give artisans a place to demonstrate and sell their work directly. Textiles, pottery and many other craft traditions appear alongside cultural performances. Themes and participating regions change between editions, so an old brochure is useful background but does not guarantee a particular stall or show this year.","rituals":["Browsing artisan and handloom stalls","Watching craft demonstrations where offered","Folk performances at the mela’s open-air stages"],"food":"The fair offers a variety of regional food choices. Check individual vendors for ingredients and dietary needs; no single cuisine represents the event.","dress":"Comfortable walking shoes and weather-appropriate clothing are more useful than formal dress for exploring the large grounds.","tips":["Ask makers about materials, technique and care instructions before buying.","Check official ticketing, gate access and the performance schedule; allow time to return to the correct exit."],"places":[["Faridabad","HR",77.31,28.41,"City-centre reference; the mela itself is at Surajkund, with designated gates."]],"sources":[["Haryana Tourism: Surajkund Crafts Mela","https://haryanatourism.gov.in/fair-and-festivals/surajkund-international-craft-mela/"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Kullu Dussehra","season":"September–October","months":[9,10],"theme":"Devotion & procession","place":"Dhalpur, Kullu","description":"Valley deities are brought to Kullu in a gathering centred on Lord Raghunath, with processions and cultural programmes.","id":"kullu-dussehra","states":["HP"],"regions":["North"],"locations":[{"state":"HP","text":"Dhalpur, Kullu"}],"native":"कुल्लू दशहरा","categories":["Devotion","Community","Music & dance"],"story":"Kullu Dussehra brings local deities and their representatives together around Lord Raghunath. A ceremonial chariot journey into Dhalpur forms a central public moment, followed by a wider fair and cultural programme. The gathering expresses relationships between valley communities as well as devotion. Its sequence differs from familiar one-day Dussehra spectacles elsewhere, so the arrival of deities, processions and performances should be planned as distinct experiences.","rituals":["Arrival of community deities and their attendants","Lord Raghunath’s ceremonial chariot procession","Cultural performances and fairground gatherings"],"food":"Explore local food through public stalls and restaurants. Sacred offerings and community meals may have separate arrangements and access rules.","dress":"Layered clothing suits outdoor viewing. Regional caps and textiles are part of local dress, not compulsory visitor attire.","tips":["Keep clear of chariot ropes, bearers and deity palanquins even when taking photographs.","Check the current Dhalpur programme and allow extra travel time around procession closures."],"places":[["Kullu","HP",77.11,31.96,"Dhalpur is associated with the main gathering; confirm current entrances and viewing areas."]],"sources":[["Himachal Tourism: Temples and deity traditions","https://himachaltourism.gov.in/destination/temples/"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Mandi Shivratri","season":"February–March","months":[2,3],"theme":"Devotion","place":"Mandi","description":"Local deities, devotees and performers gather for a celebration associated with Maha Shivratri.","id":"mandi-shivratri","states":["HP"],"regions":["North"],"locations":[{"state":"HP","text":"Mandi"}],"native":"मंडी शिवरात्रि","categories":["Devotion","Community","Arts"],"story":"Mandi Shivratri combines religious observances with a major gathering of local deities, processions and cultural events. Bhootnath Temple and the presence of Madho Rai are important within its ceremonial setting. The fair gives visitors an opportunity to understand how village deity traditions relate to the town. Evening performances, exhibitions and the religious sequence are different parts of the occasion; they may operate on separate schedules.","rituals":["Gathering of local deities and their attendants","Religious visits and ceremonial processions","Cultural evenings, exhibitions and public fair activities"],"food":"Himachali dham is associated with regional celebrations and is mentioned in tourism accounts of the fair. Confirm where meals are offered and how to join.","dress":"Respectful layers suit temple visits and outdoor evenings. Colourful local turbans are part of procession dress.","tips":["Give bearers and worshippers priority around temples and processions.","Check the daily programme before choosing between a religious observance and an evening cultural performance."],"places":[["Mandi","HP",76.93,31.71,"Town-centre reference; official programme identifies procession and fair venues."]],"sources":[["Himachal Tourism: Mandi","https://himachaltourism.gov.in/destination/mandi/"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Sarhul","season":"March–April","months":[3,4],"theme":"Nature & spring","place":"Ranchi & nearby villages","description":"Several Adivasi communities honour sacred groves and the flowering sal tree with rituals, music and dancing.","id":"sarhul","states":["JH"],"regions":["East"],"locations":[{"state":"JH","text":"Ranchi & nearby villages"}],"native":"सरहुल","categories":["Community","Devotion","Music & dance"],"story":"Sarhul welcomes spring among several Adivasi communities in Jharkhand. Sal blossoms are closely associated with the occasion, linking worship and community life to the changing season. Songs, dancing and gatherings express renewal, but names, narratives and ritual details differ between communities. A public city procession offers one way to encounter Sarhul; it should not be treated as a complete representation of every village’s sacred practices.","rituals":["Community worship associated with the spring season","Use of sal blossoms in local observances","Songs, dancing and public gatherings"],"food":"Families prepare celebratory food according to their own traditions. Ask before accepting or photographing offerings, and check ingredients with your host.","dress":"White saris with red borders appear in public celebrations, among other regional clothing. Visitors do not need to adopt community dress.","tips":["Ask permission before entering a sacred grove or approaching a ritual area.","Use a local guide or host to identify the community and meaning of the celebration rather than describing all practices as the same."],"places":[["Ranchi","JH",85.31,23.34,"Public processions and nearby community celebrations; access differs by site."]],"sources":[["Jharkhand Chief Minister’s office: Sarhul","https://cm.jharkhand.gov.in/sarhul"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Karam","season":"August–September","months":[8,9],"theme":"Nature & community","place":"Across Jharkhand","description":"Community celebrations centre on the Karam tree, with songs and dances expressing hopes for wellbeing and prosperity.","id":"karam","states":["JH"],"regions":["East"],"locations":[{"state":"JH","text":"Across Jharkhand"}],"native":"करम","categories":["Devotion","Community","Music & dance"],"story":"Karam centres on reverence for Karam devta and is observed by several communities in Jharkhand and neighbouring regions. Young people, communal singing and dance are prominent in accounts of the celebration. Its relationship with nature, wellbeing and collective life makes the ritual setting important, not merely the performance. Practices vary, so a host’s explanation of their own observance is more reliable than assuming one statewide sequence.","rituals":["Worship associated with Karam devta","Community songs and dance","Gatherings in which young people play an important role"],"food":"Offerings and shared meals follow local custom. Ask hosts about preparation and participation rather than assuming every gathering has a public feast.","dress":"Regional festive textiles and everyday dress vary by community. Choose respectful clothing and avoid handling ceremonial objects.","tips":["Ask which activities are public and where visitors may stand before a ceremony starts.","Seek permission for portraits and recordings, particularly when songs or rituals are not intended as public performances."],"places":[["Ranchi","JH",85.31,23.34,"A base for learning about local Karam traditions; arrange a specific hosted visit."]],"sources":[["Jharkhand Tourism: Festivals","https://tourism.jharkhand.gov.in/festivals"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Mysuru Dasara","season":"September–October","months":[9,10],"theme":"Royal heritage & devotion","place":"Mysuru","description":"An illuminated palace, performances and the celebrated procession make Dasara a signature Mysuru experience.","id":"mysuru-dasara","states":["KA"],"regions":["South"],"locations":[{"state":"KA","text":"Mysuru"}],"native":"ಮೈಸೂರು ದಸರಾ","categories":["Devotion","Arts","Music & dance"],"story":"Mysuru Dasara combines worship of Chamundeshwari with the city's royal and public cultural heritage. Palace illumination and performances build towards the festival's celebrated procession. Specific programmes can have separate tickets.","rituals":["Palace illumination","Classical and folk performances","The ceremonial Dasara procession"],"food":"Mysore pak is a local sweet to try; it is not exclusive to Dasara.","dress":"Comfortable clothing works for public viewing; follow dress requirements in religious venues.","tips":["Verify procession dates and viewing arrangements separately.","Book accommodation early and allow for traffic restrictions."],"places":[["Mysuru","KA",76.64,12.3,"Palace area and announced city programme locations."]],"sources":[["Incredible India: Mysuru Dasara","https://www.incredibleindia.gov.in/en/festivals-and-events/mysuru-dasara"]],"photo":null,"reviewed":"2026-10-10","destinationIds":["mysuru"]},{"name":"Onam","season":"August–September","months":[8,9],"theme":"Harvest & homecoming","place":"Across Kerala","description":"Floral pookalam designs, the onasadya feast and cultural performances celebrate the homecoming of King Mahabali.","id":"onam","states":["KL","TN"],"regions":["South"],"locations":[{"state":"KL","text":"Across Kerala"}],"native":"ഓണം","categories":["Harvest","Community","Arts"],"story":"Onam celebrates seasonal abundance and the legendary return of King Mahabali. It brings Malayali families and communities together through floral designs, hospitality and performances. Public programmes and household traditions have different schedules.","rituals":["Pookalam floral designs","An Onasadya meal served on a banana leaf","Cultural performances and community gatherings"],"food":"Sadya is a vegetarian feast with rice, vegetable dishes and payasam; menus vary by household and venue.","dress":"Kerala kasavu textiles are often worn for celebrations. Comfortable, respectful clothing is suitable for visitors.","tips":["Book a public sadya rather than assuming access to a private family meal.","Boat races are separate events: verify their dates independently."],"places":[["Thiruvananthapuram","KL",76.94,8.52,"Look for announced city cultural programmes."],["Kochi","KL",76.27,9.97,"Community celebrations and public sadya meals."]],"sources":[["Incredible India: Onam","https://www.prod.incredibleindia.gov.in/content/incredible-india-v2/en/destinations/kochi/listicles/festivals-of-kochi/onam.html"]],"photo":{"url":"https://upload.wikimedia.org/wikipedia/commons/9/94/Onam_celebration.jpg","alt":"Children performing a boat-song scene during an Onam celebration","caption":"Children singing vallappaattu during Onam, 2010. Historical photograph.","author":"Ramjchandran","source":"https://commons.wikimedia.org/wiki/File:Onam_celebration.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},"reviewed":"2026-10-10","destinationIds":["kochi"]},{"name":"Vishu","season":"April","months":[4],"theme":"Seasonal celebration","place":"Across Kerala","description":"The day begins with viewing the auspicious Vishukkani arrangement, followed by gifts and family meals.","id":"vishu","states":["KL"],"regions":["South"],"locations":[{"state":"KL","text":"Across Kerala"}],"native":"വിഷു","categories":["Community","Devotion","Harvest"],"story":"Vishu marks an auspicious solar-calendar occasion in Kerala, usually during April. The first sight of the day, Vishukkani, is central: an arrangement of produce, flowers, a mirror and other meaningful objects is prepared with care. Gifts from elders and a shared feast connect the ritual to family life. Household practices and temple observances differ, and Vishu should not be treated as interchangeable with Onam or every other regional New Year.","rituals":["Viewing the Vishukkani arrangement on waking","Vishukkaineetam gifts from elders","Family meals and temple visits where observed"],"food":"Vishu sadya offers a range of Kerala dishes; menus vary. Vishu katta is another regional preparation associated with the occasion.","dress":"Kerala saris and mundu are familiar festive choices. Temple dress requirements may be more specific, so check before visiting.","tips":["A household Vishukkani is an intimate family moment: arrange a host’s invitation rather than arriving unannounced.","If booking a festive meal, confirm its menu and service time independently of temple schedules."],"places":[["Thrissur","KL",76.21,10.53,"A Kerala cultural base; confirm the specific temple or hosted family arrangements."]],"sources":[["Kerala Tourism: Vishu","https://www.keralatourism.org//vishu/"],["Kerala Tourism: Vishu katta","https://www.keralatourism.org/kerala-food/vishu-katta/164/"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Bhagoria","season":"February–March","months":[2,3],"theme":"Community fair","place":"Jhabua & Alirajpur","description":"Bhil and Bhilala communities gather at lively fairs before Holi, with music, dancing and market stalls.","id":"bhagoria","states":["MP"],"regions":["Central"],"locations":[{"state":"MP","text":"Jhabua & Alirajpur"}],"native":"भगोरिया","categories":["Harvest","Community","Music & dance"],"story":"Bhagoria is a series of fairs associated especially with Bhil and Bhilala communities in western Madhya Pradesh. Held around local market days before Holi, the gatherings connect the end of the harvest with music, dance, social visits and trade. Jhabua, Alirajpur, Dhar and Khargone are among the regions associated with it. Reducing Bhagoria to a sensational story about courtship overlooks its agricultural, commercial and community importance.","rituals":["Market-day gatherings at local haats","Traditional music and group dancing","Exchange of colour where participants welcome it"],"food":"Market stalls offer food and seasonal produce. Ask vendors about ingredients; everyday regional cuisine and ritual food are not necessarily the same.","dress":"Bright clothing and silver ornaments appear in community dress. Ask permission for photographs rather than treating participants as exhibits.","tips":["Find the local haat calendar, since different towns celebrate on different days.","Ask before applying colour, joining a dance or photographing personal interactions; participation should always be welcome."],"places":[["Jhabua","MP",74.59,22.77,"Base for regional haats; identify the exact market and day locally."]],"sources":[["Madhya Pradesh Tourism: Bhagoria","https://www.mptourism.com/bhagoria-tribal-festival.htm"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Khajuraho Dance Festival","season":"February","months":[2],"theme":"Classical arts","place":"Khajuraho","description":"Indian classical dance traditions are showcased against the backdrop of Khajuraho’s temple heritage.","id":"khajuraho-dance-festival","states":["MP"],"regions":["Central"],"locations":[{"state":"MP","text":"Khajuraho"}],"native":"","categories":["Arts","Music & dance"],"story":"Khajuraho Dance Festival presents Indian classical dance in the setting of Khajuraho’s monumental heritage. It is a curated arts programme, with named performers and scheduled presentations, rather than a single religious rite shared by all visitors. Different dance traditions bring distinctive movement, music and storytelling. Reading the programme before attending makes it easier to understand what you are watching and to choose performances that interest you.","rituals":["Scheduled classical dance recitals","Musical accompaniment and expressive storytelling","Associated cultural activities when included by organisers"],"food":"Food is part of the wider visitor experience rather than a defining ritual. Plan a meal around performance times and use the designated eating areas.","dress":"Comfortable, respectful evening clothing is suitable for audiences. Performers’ costumes belong to particular dance traditions.","tips":["Check the current performance roster, venue and entry arrangements; an earlier edition’s lineup is not a promise.","Keep phones silent and follow rules on flash, filming and movement during a recital; visit the monuments separately if required."],"places":[["Khajuraho","MP",79.92,24.83,"Town reference near the temple heritage area; current festival venue must be confirmed."]],"sources":[["Madhya Pradesh Tourism: Khajuraho Dance Festival","https://www.mptourism.com/khajuraho-dance-festival.htm"]],"reviewed":"2026-10-11","photo":null,"destinationIds":["khajuraho"]},{"name":"Ganesh Chaturthi","season":"August–September","months":[8,9],"theme":"Devotion & community","place":"Mumbai & Pune","description":"Ganesha idols are welcomed into homes and public pandals, with prayers, modak sweets and immersion processions.","id":"ganesh-chaturthi","states":["MH","GA","KA","TG"],"regions":["West","South"],"locations":[{"state":"MH","text":"Mumbai & Pune"}],"native":"गणेश चतुर्थी","categories":["Devotion","Arts","Community"],"story":"Ganesh Chaturthi welcomes Ganesha into homes and public pandals. Maharashtra's community celebrations combine worship, craftsmanship and collective organisation. Household observances vary in duration, so immersion days are not identical everywhere.","rituals":["Installation of Ganesha idols","Aarti and offerings","Visarjan immersion processions"],"food":"Modak sweets are strongly associated with Ganesha; recipes and offerings vary.","dress":"Respectful, comfortable clothing is suitable; follow temple or pandal instructions.","tips":["Use designated viewing areas for processions and immersion.","Allow extra time for queues and temporary road closures."],"places":[["Mumbai","MH",72.88,19.08,"Major public pandals and immersion routes."],["Pune","MH",73.86,18.52,"Neighbourhood mandals and processions."]],"sources":[["Incredible India: Ganesh Chaturthi","https://www.incredibleindia.gov.in/en/festivals-and-events/maharashtra/ganesh-chaturthi"]],"photo":{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Ganesh_Chaturthi_1.jpg/960px-Ganesh_Chaturthi_1.jpg","alt":"Ganesha idol surrounded by pink flowers beside a coconut and ceremonial vessels","caption":"Ganesh Chaturthi worship in India, August 2020. Historical photograph.","author":"Yugaljoshi","source":"https://commons.wikimedia.org/wiki/File:Ganesh_Chaturthi_1.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},"reviewed":"2026-10-10","destinationIds":["mumbai"]},{"name":"Gudi Padwa","season":"March–April","months":[3,4],"theme":"Marathi New Year","place":"Across Maharashtra","description":"Families raise decorated gudis outside their homes to welcome the new year.","id":"gudi-padwa","states":["MH"],"regions":["West"],"locations":[{"state":"MH","text":"Across Maharashtra"}],"native":"गुढीपाडवा","categories":["Community","Devotion","Arts"],"story":"Gudi Padwa welcomes the Marathi New Year at the beginning of Chaitra. A gudi, raised outside the home, gives the celebration its distinctive visual symbol and expresses auspiciousness and renewal. Household prayers and meals sit alongside public shobhayatra processions in places such as Pune and Mumbai. It shares a seasonal setting with other regional New Year celebrations, but its customs and local programmes deserve their own attention.","rituals":["Raising and worshipping a decorated gudi","Making rangoli and decorating entrances","Community shobhayatra processions where announced"],"food":"Puran poli and shrikhand are familiar festive foods. Neem and jaggery can express acceptance of life’s bitter and sweet experiences; customs vary.","dress":"Saris, kurtas and regional festive clothing are common. Comfortable footwear is useful for public procession viewing.","tips":["View household gudis from public space unless invited inside.","Confirm the route and time of the particular shobhayatra, and leave clear space for performers and worshippers."],"places":[["Pune","MH",73.86,18.52,"Public processions and household traditions; check neighbourhood-specific schedules."]],"sources":[["Maharashtra Tourism: Gudi Padwa","https://maharashtratourism.gov.in/festivals/gudi-padwa/"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Yaoshang","season":"February–March","months":[2,3],"theme":"Spring","place":"Imphal & surrounding areas","description":"A multiday spring celebration combines devotional traditions, local sports and thabal chongba dancing.","id":"yaoshang","states":["MN"],"regions":["Northeast"],"locations":[{"state":"MN","text":"Imphal & surrounding areas"}],"native":"","categories":["Community","Music & dance"],"story":"Yaoshang is an important spring celebration in Manipur, traditionally extending over several days around the full moon of Phalguna. It is especially associated with Meitei cultural life. Thabal Chongba, in which participants form a circle and dance together, is a recognisable part of the festive season. Community programmes vary, so the festival is best understood through a particular neighbourhood’s arrangements rather than a single assumed statewide timetable.","rituals":["Community gatherings over the spring festive period","Thabal Chongba circle dancing","Local cultural activities according to the neighbourhood programme"],"food":"Explore local food through public vendors or a host. Festival hospitality does not imply that every household meal is open to visitors.","dress":"Participants may wear Manipuri textiles and festive clothes. Ask hosts about appropriate clothing if invited to join an activity.","tips":["Obtain the local programme and confirm that visitors may attend the dance gathering.","Join only when invited, follow the group’s lead and ask before photographing people; confirm current local travel arrangements before making plans."],"places":[["Imphal","MN",93.94,24.82,"Neighbourhood celebrations have separate organisers and access arrangements."]],"sources":[["Manipur Tourism: Festivals in Manipur","https://manipurtourism.gov.in/festivals-in-manipur/"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Sangai Festival","season":"November","months":[11],"theme":"Cultural showcase","place":"Manipur; venues vary","description":"A tourism festival presents the state’s dance, crafts, food and cultural traditions.","id":"sangai-festival","states":["MN"],"regions":["Northeast"],"locations":[{"state":"MN","text":"Manipur; venues vary"}],"native":"","categories":["Arts","Community","Music & dance"],"story":"Sangai Festival is an organised showcase of Manipur’s arts, crafts, cuisine and sporting traditions. It takes its name from the state’s distinctive brow-antlered deer. Past editions have brought performances, handlooms and demonstrations together across several venues, helping visitors encounter the diversity of the state. This is an annual event whose delivery depends on organiser announcements: a historical programme should not be presented as confirmation of a forthcoming edition.","rituals":["Announced dance and music performances","Handloom and craft exhibitions","Demonstrations of indigenous games when programmed"],"food":"Past food programmes have included dishes such as eromba, singju and fish curry. Ingredients vary; ask specifically about fermented fish and vegetarian preparation.","dress":"Comfortable clothing suits exhibition grounds. Performance costumes represent distinct communities rather than one universal Manipuri outfit.","tips":["Confirm that the edition is going ahead, then check venues, tickets and local travel arrangements.","Plan transport between venues instead of assuming all activities occur in one fairground; ask makers before photographing their work."],"places":[["Imphal","MN",93.94,24.82,"Planning base; festival venues may also be outside the city."]],"sources":[["Manipur Tourism: Sangai Festival background and past programme","https://manipurtourism.gov.in/sangai-festival-2018/"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Wangala","season":"October–November","months":[10,11],"theme":"Harvest","place":"Garo Hills","description":"Garo communities celebrate the harvest with drumming and dancing, giving thanks to the sun deity.","id":"wangala","states":["ML"],"regions":["Northeast"],"locations":[{"state":"ML","text":"Garo Hills"}],"native":"","categories":["Harvest","Music & dance","Community"],"story":"Wangala is a Garo harvest celebration associated with gratitude to Saljong and the agricultural cycle. Drumming and coordinated dancing are important public expressions of the occasion, especially in the well-known Hundred Drums presentation. Village observances have their own settings and calendars; the organised showcase should not be mistaken for the only form of Wangala. Learning from a Garo host helps connect the performances to their cultural and spiritual meaning.","rituals":["Harvest thanksgiving observances","Rhythmic group dancing accompanied by drums","Community gatherings and organised cultural presentations"],"food":"Garo food and traditional beverages may be offered. Ask about ingredients and alcohol content; accepting a drink is not necessary to appreciate the gathering.","dress":"Community textiles and headpieces carry cultural meaning. Visitors can wear practical clothes and ask before photographing or handling ornaments.","tips":["Check the specific village or showcase programme instead of assuming one date applies throughout the Garo Hills.","Keep dance lines and drummers’ space clear, and seek guidance before approaching ritual areas."],"places":[["Tura","ML",90.22,25.51,"Base for Garo Hills visits; verify the actual Wangala ground separately."]],"sources":[["Meghalaya Tourism: Wangala","https://www.meghalayatourism.in/explore/about-meghalaya/dance-music/wangala-dance/"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Nongkrem Dance Festival","season":"Autumn; dates vary","months":[10,11],"theme":"Community & thanksgiving","place":"Smit, near Shillong","description":"Khasi ceremonial traditions and dances express thanksgiving and prayers for prosperity.","id":"nongkrem-dance-festival","states":["ML"],"regions":["Northeast"],"locations":[{"state":"ML","text":"Smit, near Shillong"}],"native":"","categories":["Harvest","Devotion","Arts"],"story":"Nongkrem is a Khasi thanksgiving festival held at Smit, the traditional seat of Hima Khyrim near Shillong. Its ceremonies connect prayers for prosperity and a good harvest with the responsibilities of the Syiem and religious authorities. The public dance is one part of a larger sacred observance, rather than a performance arranged simply for visitors. Women and men have distinct roles, and the ceremonial dress, music and movement carry community meanings. Autumn is a useful planning window, but the organising authorities announce the actual programme.","rituals":["Thanksgiving ceremonies associated with the Pomblang observance","Women and men performing ceremonial dances in the courtyard","Traditional instrumental music accompanying the dancers"],"food":"Look for locally run Khasi food stalls nearby; refreshments for visitors are separate from ceremonial offerings. Ask about ingredients and vegetarian options.","dress":"Dancers wear elaborate Khasi ceremonial textiles and ornaments. Visitors can wear comfortable, respectful everyday clothing.","tips":["Stay outside the designated dancing space and ask before photographing ceremonial participants.","Confirm the principal dance day before arranging transport from Shillong; allow time for traffic near Smit."],"places":[["Smit","ML",91.9,25.52,"Approximate village centre; follow local directions to the ceremonial courtyard."]],"sources":[["Meghalaya Government: Nongkrem Dance","https://meghalaya.gov.in/index.php/nongkrem-dance"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Chapchar Kut","season":"March","months":[3],"theme":"Spring","place":"Aizawl & across Mizoram","description":"A Mizo spring festival with music, traditional dress and dances including the bamboo dance, Cheraw.","id":"chapchar-kut","states":["MZ"],"regions":["Northeast"],"locations":[{"state":"MZ","text":"Aizawl & across Mizoram"}],"native":"","categories":["Harvest","Community","Arts"],"story":"Chapchar Kut is a spring celebration rooted in the agricultural rhythm of jhum cultivation. It marks a pause after the demanding work of clearing land, bringing people together through music, dancing and shared festivities. Contemporary public programmes also celebrate Mizo cultural identity, textiles and performance. Aizawl is a useful starting point for a visitor, though local communities hold their own events. The usual spring season should not be treated as a fixed annual date: the announced programme determines when the main gathering takes place.","rituals":["Traditional dances and songs performed by community groups","Drum and cymbal accompaniment","Public gatherings showcasing Mizo dress and cultural expression"],"food":"Bamboo-shoot and leafy vegetable preparations are regional foods to explore. Menus vary by vendor, so ask about meat or fermented ingredients.","dress":"Performers often wear bright Mizo woven clothing and headgear; visitors do not need ceremonial costume.","tips":["Check the published Aizawl programme and venue before making bookings.","Watch organised dances from the audience area; join participatory activities only when invited."],"places":[["Aizawl","MZ",92.72,23.73,"City centre reference; confirm the announced festival ground."]],"sources":[["Mizoram Tourism: Chapchar Kut","https://mizoramtourism.com/festivals/1"],["Aizawl District: Chapchar Kut","https://aizawl.nic.in/festival/chapchar-kut-festival/"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Mim Kut","season":"August–September","months":[8,9],"theme":"Harvest & remembrance","place":"Mizo communities","description":"A traditional maize-season observance combines remembrance of departed relatives with community customs.","id":"mim-kut","states":["MZ"],"regions":["Northeast"],"locations":[{"state":"MZ","text":"Mizo communities"}],"native":"","categories":["Harvest","Community"],"story":"Mim Kut is one of the traditional seasonal festivals documented by Mizoram Tourism, which describes it as the Maize Festival. It belongs to the agricultural and cultural heritage of Mizo communities, with singing, dancing and communal enjoyment associated with the celebration. Accounts of older practices and present-day gatherings can differ, so a historical description should not be assumed to describe every household today. Unlike a large annual ticketed event, a local observance may have no advertised visitor programme. Ask a community host what is being celebrated and which activities welcome guests.","rituals":["Community songs and dances where locally organised","Gatherings connected with the seasonal harvest","Sharing food according to the host community’s customs"],"food":"Harvest foods and local meals vary between communities. Historical accounts mention rice beer, but visitors should not assume it is served or required.","dress":"Woven Mizo clothing may feature in cultural programmes. Everyday respectful dress is appropriate unless organisers advise otherwise.","tips":["Confirm that a public gathering is taking place before planning travel around it.","Ask permission before entering family gatherings or photographing participants."],"places":[["Aizawl","MZ",92.72,23.73,"Planning base for local cultural information; not a guaranteed public festival venue."]],"sources":[["Mizoram Tourism: Festivals","https://mizoramtourism.com/festivals"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Hornbill Festival","season":"December","months":[12],"theme":"Cultural showcase","place":"Kisama, near Kohima","description":"Naga communities share performances, crafts, food and traditions at a major annual cultural gathering.","id":"hornbill-festival","states":["NL"],"regions":["Northeast"],"locations":[{"state":"NL","text":"Kisama, near Kohima"}],"native":"Hornbill Festival","categories":["Arts","Community","Music & dance"],"story":"Organised as a cultural showcase since 2000, Hornbill brings together different Naga communities. It offers performances, crafts and food alongside contemporary events. The shared programme does not replace each community's own festivals or distinct traditions.","rituals":["Cultural presentations at Kisama","Craft and textile demonstrations","Music and community food stalls"],"food":"Stalls offer different Naga cuisines. Ask vendors about ingredients, spice levels and vegetarian options.","dress":"Community textiles and ornaments have specific meanings; ask before borrowing, handling or photographing them closely.","tips":["Check the current official programme and visitor requirements before booking.","Ask performers before portraits, and keep performance areas clear."],"places":[["Kisama Heritage Village","NL",94.12,25.62,"Main cultural showcase near Kohima; programme and access are organiser-dependent."]],"sources":[["Ministry of Tourism: Hornbill Festival","https://www.utsav.gov.in/view-event/hornbill-festival"]],"photo":{"url":"https://upload.wikimedia.org/wikipedia/commons/9/9a/Hornbill_festival.jpg","alt":"Participant wearing traditional dress at the Hornbill Festival in Kisama","caption":"Hornbill Festival at Kisama, 2024. Historical photograph.","author":"JyotiPN","source":"https://commons.wikimedia.org/wiki/File:Hornbill_festival.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},"reviewed":"2026-10-10","destinationIds":["kisama"]},{"name":"Moatsu","season":"May","months":[5],"theme":"Agriculture & community","place":"Ao communities, Mokokchung","description":"After sowing, Ao communities celebrate with songs, dances and communal gatherings.","id":"moatsu","states":["NL"],"regions":["Northeast"],"locations":[{"state":"NL","text":"Ao communities, Mokokchung"}],"native":"","categories":["Harvest","Community","Arts"],"story":"Moatsu is an Ao Naga festival associated with community bonding after agricultural work. The Ministry of Tourism describes a three-day celebration in May, bringing people together through shared festivities. Its importance lies in the relationships renewed among neighbours and families, alongside cultural expression. Mokokchung and surrounding Ao villages provide the relevant geographical context, but an announced public event and a village’s own observance may have different arrangements. Treat the general season as an introduction and seek the host community’s programme before making a special journey.","rituals":["Community gatherings and shared celebrations","Traditional music and dance in organised programmes","Hospitality that renews relationships among participants"],"food":"Food is arranged by the host community; ask what is included before accepting a meal, particularly if you avoid meat or particular ingredients.","dress":"Ao shawls and traditional clothing may be worn by participants. Ceremonial garments have meanings that a local guide can explain.","tips":["Contact a local host to identify public events in the Mokokchung area.","Ask before photographing people or joining a group meal; private hospitality is by invitation."],"places":[["Mokokchung","NL",94.52,26.32,"Town centre reference for Ao community celebrations in the surrounding area."]],"sources":[["Ministry of Tourism: Moatsu Festival","https://utsav.gov.in/public/view-event/moatsu-festival"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Rath Yatra","season":"June–July","months":[6,7],"theme":"Chariot festival","place":"Puri","description":"The deities Jagannath, Balabhadra and Subhadra travel in monumental wooden chariots through Puri.","id":"rath-yatra","states":["OR"],"regions":["East"],"locations":[{"state":"OR","text":"Puri"}],"native":"ରଥଯାତ୍ରା","categories":["Devotion","Arts","Community"],"story":"Puri's Rath Yatra brings Jagannath, Balabhadra and Subhadra into a public chariot procession. The journey forms part of a larger cycle of observances, including the return journey, which must be checked separately.","rituals":["Wooden chariot construction","The outward chariot procession","Later return observances"],"food":"Mahaprasad is associated with Jagannath traditions; seek guidance on authorised distribution.","dress":"Wear respectful clothing and practical footwear for long periods outdoors.","tips":["Use authorised viewing arrangements rather than entering dense chariot crowds.","Temple entry restrictions differ from access to the public procession."],"places":[["Puri","OR",85.83,19.81,"Grand Road procession corridor; access follows local arrangements."]],"sources":[["Incredible India: Rath Yatra","https://www.incredibleindia.gov.in/en/festivals-and-events/odisha/rath-yatra"]],"photo":{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/34/Rath_Yatra_Puri.jpg/960px-Rath_Yatra_Puri.jpg","alt":"Three brightly decorated festival chariots lit at night with visitors in front","caption":"Rath Yatra chariots near Gundicha Temple in Puri, July 2011. Historical photograph.","author":"Zephyrmaten","source":"https://commons.wikimedia.org/wiki/File:Rath_Yatra_Puri.jpg","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0/"},"reviewed":"2026-10-10","destinationIds":["puri"]},{"name":"Raja Parba","season":"June","months":[6],"theme":"Monsoon & earth","place":"Across Odisha","description":"A celebration associated with the earth’s fertility, featuring swings, pitha and a pause in agricultural work.","id":"raja-parba","states":["OR"],"regions":["East"],"locations":[{"state":"OR","text":"Across Odisha"}],"native":"","categories":["Harvest","Community"],"story":"Raja Parba celebrates womanhood and the renewal of the earth at the approach of the monsoon in Odisha. The three-day observance symbolically gives Mother Earth rest, with agricultural work traditionally paused. Swings, games, new clothes and festive food are prominent parts of the celebration, particularly for girls and women. It is both a household occasion and a community festival; public Raja events can provide a welcoming introduction for visitors. Customs vary across Odisha, and the symbolism is best understood through the voices of the people who practise it.","rituals":["Decorated swings and traditional games","A symbolic pause in agricultural work","Family and community gatherings celebrating seasonal renewal"],"food":"Pitha and other festive treats are a good starting point for exploring Odia food. Ask vendors about ingredients and preparation rather than assuming a single standard menu.","dress":"New festive clothing is common; visitors can choose light, comfortable clothing suitable for outdoor gatherings.","tips":["Look for announced public Raja programmes in Bhubaneswar rather than entering private celebrations.","Ask permission before using a community swing and wait for organisers to supervise children."],"places":[["Bhubaneswar","OR",85.82,20.3,"City centre reference; public Raja venues vary by edition."]],"sources":[["Odisha Tourism: Raja Parba and celebrations","https://odishatourism.gov.in/en/events"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Vaisakhi","season":"April","months":[4],"theme":"Harvest & Sikh heritage","place":"Amritsar & across Punjab","description":"Harvest celebrations coincide with the commemoration of the formation of the Khalsa, with gurdwara visits and community meals.","id":"vaisakhi","states":["PB","HR"],"regions":["North"],"locations":[{"state":"PB","text":"Amritsar & across Punjab"}],"native":"ਵਿਸਾਖੀ","categories":["Harvest","Devotion","Community"],"story":"Vaisakhi brings together Punjab's harvest season and the Sikh commemoration of the formation of the Khalsa. Gurdwara visits, service and community meals are important, alongside local fairs and cultural programmes.","rituals":["Gurdwara worship and kirtan","Community langar","Local fairs and processions"],"food":"Langar is a communal meal grounded in service and equality; follow the volunteers' guidance.","dress":"Cover your head and remove shoes where required in a gurdwara.","tips":["Ask about visitor procedures at each religious venue.","Keep paths clear and ask before photographing worshippers."],"places":[["Amritsar","PB",74.87,31.63,"Gurdwara observances and community gatherings."],["Bathinda","PB",74.95,30.21,"Local Vaisakhi fair and religious celebrations."]],"sources":[["Incredible India: Vaisakhi Mela","https://www.incredibleindia.gov.in/en/festivals-and-events/punjab/vaisakhi-mela-bathinda-april"]],"photo":null,"reviewed":"2026-10-10","destinationIds":["amritsar"]},{"name":"Lohri","season":"January","months":[1],"theme":"Winter celebration","place":"Across Punjab","description":"Families and communities gather around bonfires with folk songs and seasonal foods.","id":"lohri","states":["PB"],"regions":["North"],"locations":[{"state":"PB","text":"Across Punjab"}],"native":"","categories":["Harvest","Community"],"story":"Lohri is a winter folk celebration strongly associated with Punjab and Punjabi communities elsewhere. An evening bonfire becomes a focus for gathering, singing and sharing seasonal treats. It expresses warmth and companionship during the cold season, and a family’s celebration may also mark a recent marriage or the arrival of a child. The character of the occasion depends on the hosts: a neighbourhood gathering, family party and organised cultural programme offer different experiences. A public programme is the simplest route for visitors who do not have a personal invitation.","rituals":["Gathering around an evening bonfire","Folk songs and dancing in community celebrations","Sharing seasonal snacks among friends and neighbours"],"food":"Peanuts, popcorn, revri and gajak are familiar Lohri treats. Sesame and nuts are common ingredients, so check allergens before sharing.","dress":"Punjabi festive clothing may appear at organised events. Warm layers and practical footwear are useful for an outdoor evening.","tips":["Keep loose clothing and children away from the fire and follow the organisers’ viewing boundaries.","Ask a local host about a public celebration; private family festivities are not open-access attractions."],"places":[["Amritsar","PB",74.87,31.63,"City centre reference for Punjabi winter celebrations."]],"sources":[["Incredible India: Celebrating Lohri","https://www.incredibleindia.gov.in/en/punjab/amritsar/celebrating-lohri-the-punjabi-way"],["Delhi Tourism: Lohri","https://delhitourism.gov.in/dt/festivals/lohri.html"]],"reviewed":"2026-10-11","photo":null,"destinationIds":["amritsar"]},{"name":"Gangaur","season":"March–April","months":[3,4],"theme":"Devotion & spring","place":"Jaipur & Udaipur","description":"Women honour Gauri with rituals, decorated images and colourful processions.","id":"gangaur","states":["RJ"],"regions":["West"],"locations":[{"state":"RJ","text":"Jaipur & Udaipur"}],"native":"गणगौर","categories":["Devotion","Arts","Community"],"story":"Gangaur honours Gauri and is especially associated with women's devotional traditions in Rajasthan. Udaipur's Mewar Festival overlaps with these celebrations, giving the occasion a distinctive lakeside expression.","rituals":["Worship of decorated images","Songs and processions","Local cultural programmes"],"food":"Seek regional sweets and seasonal dishes; customs vary between families and towns.","dress":"Colourful saris and regional dress are common in processions.","tips":["Photograph respectfully without blocking processions.","Check the local route rather than assuming all cities share one programme."],"places":[["Udaipur","RJ",73.68,24.58,"Gangaur traditions around the old city and lakeside."],["Jaipur","RJ",75.79,26.91,"City processions subject to annual announcements."]],"sources":[["Incredible India: Mewar Festival","https://www.incredibleindia.gov.in/en/festivals-and-events/rajasthan/mewar-festival-2026"]],"photo":null,"reviewed":"2026-10-10","destinationIds":["jaipur","udaipur"]},{"name":"Pushkar Fair","season":"October–November","months":[10,11],"theme":"Pilgrimage & fair","place":"Pushkar","description":"Around Kartik Purnima, pilgrims and visitors gather for a traditional fair, cultural events and lakeside rituals.","id":"pushkar-fair","states":["RJ"],"regions":["West"],"locations":[{"state":"RJ","text":"Pushkar"}],"native":"","categories":["Community","Arts"],"story":"Pushkar Fair brings together livestock trading, pilgrimage and a public cultural fair in Rajasthan. The town’s lake, temples, markets and fairground create several overlapping experiences, so the most useful itinerary depends on whether you want to explore craft stalls, cultural performances or the religious setting. The trading activity and public entertainment do not necessarily peak on the same day. Pushkar’s sacred lake remains a place of worship during the festivities, and its ghats should be approached with the same care as a temple rather than as a photographic stage.","rituals":["Livestock trading and fairground activity","Craft and textile stalls alongside cultural programmes","Pilgrimage and worship around Pushkar Lake"],"food":"Explore the town’s vegetarian meals and sweet shops; fairground vendors offer snacks, but menus and hygiene arrangements differ.","dress":"Comfortable walking clothes, sun protection and a layer for the evening work well; dress respectfully at the ghats.","tips":["Check separate schedules for livestock activity and staged events before choosing your dates.","Ask before photographing traders, avoid obstructing animals and confirm any activity’s price before agreeing."],"places":[["Pushkar","RJ",74.55,26.49,"Town centre reference; lake ghats and fairground are different locations."]],"sources":[["Incredible India: Pushkar Camel Fair","https://www.incredibleindia.gov.in/en/festivals-and-events/pushkar-camel-fair"],["Incredible India: Pushkar","https://www.prod.incredibleindia.gov.in/content/incredible-india-v2/en/destinations/ajmer/pushkar.html"]],"reviewed":"2026-10-11","photo":null,"destinationIds":["pushkar"]},{"name":"Losoong / Namsoong","season":"December–January","months":[12,1],"theme":"Harvest & New Year","place":"Across Sikkim","description":"Bhutia and Lepcha communities mark seasonal renewal through their distinct traditions and celebrations.","id":"losoong-namsoong","states":["SK"],"regions":["Northeast"],"locations":[{"state":"SK","text":"Across Sikkim"}],"native":"","categories":["Harvest","Community","Devotion"],"story":"Losoong and Namsoong are closely associated seasonal celebrations in Sikkim, observed among Bhutia and Lepcha communities respectively. The period celebrates the harvest and includes family gatherings, while associated monastery programmes may feature ceremonial cham dances. The Government of Sikkim also notes traditional skills such as archery. These related observances should not erase differences between communities or be confused with Losar. A monastery’s dance programme can take place before the main family festival, making local confirmation especially important for visitors.","rituals":["Family and community harvest celebrations","Cham dances at participating monasteries on their own schedules","Traditional games or archery where organised"],"food":"Family meals reflect local traditions and preferences. Ask hosts about the menu; a regional dish available in Gangtok is not automatically a ceremonial food.","dress":"Traditional Bhutia and Lepcha clothing may be seen at celebrations. Bring warm layers for winter outdoor viewing.","tips":["Confirm the specific monastery’s programme rather than assuming all dances happen on the same day.","Remain outside the ritual performance area and follow monastery photography rules."],"places":[["Gangtok","SK",88.61,27.33,"Planning base; confirm individual monastery and community venues."]],"sources":[["Government of Sikkim: Festivals","https://www.sikkim.gov.in/KnowSikkim/about-sikkim/festivals-in-sikkim"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Pongal","season":"January","months":[1],"theme":"Harvest","place":"Across Tamil Nadu","description":"Families prepare freshly harvested rice in a ceremonial pot and honour the sun and cattle over several days.","id":"pongal","states":["TN","PY"],"regions":["South"],"locations":[{"state":"TN","text":"Across Tamil Nadu"},{"state":"PY","text":"Puducherry & Karaikal"}],"native":"பொங்கல்","categories":["Harvest","Community"],"story":"Pongal expresses gratitude for the harvest, the sun and the animals that support farming. The festival unfolds through several days with different meanings, connecting Tamil households to the agricultural season.","rituals":["Cooking freshly harvested rice until the pot overflows","Kolam designs at entrances","Mattu Pongal celebrations honouring cattle"],"food":"Sweet sakkarai pongal is made with rice and jaggery; other dishes vary by household.","dress":"Saris and veshtis are common festive clothing, though there is no universal visitor dress requirement.","tips":["Ask permission before joining household or village ceremonies.","Treat animal-related events as separate programmes with their own access rules."],"places":[["Madurai","TN",78.12,9.93,"Tamil harvest traditions in and around the city."],["Puducherry","PY",79.81,11.94,"Community and household Pongal celebrations."]],"sources":[["Incredible India: Pongal Festival","https://www.prod.incredibleindia.gov.in/content/incredible-india-v2/en/destinations/coimbatore/pongal-festival.html"]],"photo":{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Pongal_Festival.jpg/960px-Pongal_Festival.jpg","alt":"People gathered around decorated cooking pots and a colourful ground design for Pongal","caption":"Pongal celebration in India, January 2024. Historical photograph.","author":"Hishampgm","source":"https://commons.wikimedia.org/wiki/File:Pongal_Festival.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},"reviewed":"2026-10-10","destinationIds":[]},{"name":"Tamil Puthandu","season":"April","months":[4],"theme":"Tamil New Year","place":"Across Tamil Nadu","description":"Temple visits, festive meals and decorated entrances welcome the Tamil New Year.","id":"tamil-puthandu","states":["TN"],"regions":["South"],"locations":[{"state":"TN","text":"Across Tamil Nadu"}],"native":"புத்தாண்டு","categories":["Community","Devotion"],"story":"Puthandu marks the opening of the Tamil month of Chithirai and the beginning of the Tamil New Year. It is a time for family visits, greetings and renewal, with household decorations and worship forming part of many celebrations. Kolam designs at entrances welcome the occasion, while special meals bring generations together. Tamil communities around the world observe the festival, and households vary in how they combine religious and cultural customs. In Tamil Nadu, a temple visit can form part of the day, but each temple sets its own arrangements.","rituals":["Kolam designs and decorated household entrances","New Year greetings and seeking elders’ blessings","Special worship and family meals"],"food":"Mango pachadi is a well-known seasonal preparation; festive meals can also include rice, vegetable dishes, vadai and payasam. Household recipes differ.","dress":"New or festive clothing is common. Follow the individual temple’s dress requirements if you plan to enter.","tips":["Confirm temple opening and entry arrangements before setting out.","Do not confuse Tamil New Year with the separate multi-day Chithirai festival programme in Madurai."],"places":[["Chennai","TN",80.27,13.08,"City reference for Tamil New Year celebrations and temple visits."]],"sources":[["Ministry of Tourism: Tamil New Year","https://utsav.gov.in/public/view-event/tamil-new-year-arulmigu-meenakshi-sundareshwarar-temple-1"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Bathukamma","season":"September–October","months":[9,10],"theme":"Floral celebration","place":"Hyderabad & across Telangana","description":"Women arrange seasonal flowers in tiered stacks and gather around them to sing and celebrate.","id":"bathukamma","states":["TG"],"regions":["South"],"locations":[{"state":"TG","text":"Hyderabad & across Telangana"}],"native":"బతుకమ్మ","categories":["Community","Devotion","Arts"],"story":"Bathukamma celebrates seasonal flowers and the goddess through a distinctly Telangana tradition. Women arrange tiered floral stacks and gather around them to sing, before concluding celebrations at local water bodies.","rituals":["Building layered flower arrangements","Singing in circles around the flowers","Local processions and immersion traditions"],"food":"Shared offerings vary by day; maleeda is associated with celebrations.","dress":"Festive saris and regional textiles are common; observe local guidance when joining a gathering.","tips":["Ask a host before joining a community circle.","Use designated viewing areas and protect the flowers and waterside space."],"places":[["Hyderabad","TG",78.49,17.39,"Public gatherings and neighbourhood celebrations; venues vary each year."]],"sources":[["Incredible India: Bathukamma","https://www.incredibleindia.gov.in/en/festivals-and-events/bathukamma"]],"photo":null,"reviewed":"2026-10-10","destinationIds":["hyderabad"]},{"name":"Bonalu","season":"July–August","months":[7,8],"theme":"Devotion","place":"Hyderabad & Secunderabad","description":"Devotees offer decorated pots of food to the goddess Mahakali, accompanied by local processions.","id":"bonalu","states":["TG"],"regions":["South"],"locations":[{"state":"TG","text":"Hyderabad & Secunderabad"}],"native":"బోనాలు","categories":["Devotion","Community"],"story":"Bonalu is a Telangana festival of devotion and thanksgiving to Mahakali. In Hyderabad, Secunderabad and other communities, women carry decorated pots containing a prepared food offering to the goddess. The name is associated with the meal offered, and the procession combines devotion with strong neighbourhood participation. Celebrations take place through the month of Ashadam, with different temples and localities following their own schedules. A visitor should therefore choose a particular temple programme rather than assume there is one citywide festival day.","rituals":["Preparing and carrying the bonam offering in decorated pots","Temple worship dedicated to Mahakali","Neighbourhood processions and accompanying music"],"food":"The bonam is a sacred food offering; descriptions include cooked rice, jaggery and curd. Preparations vary, and offerings are not general visitor refreshments.","dress":"Women carrying offerings often wear festive traditional attire. Visitors should dress respectfully and leave room for worshippers.","tips":["Check the schedule for the particular Hyderabad or Secunderabad temple you wish to visit.","Avoid standing in the procession’s path or interrupting someone carrying an offering for a photograph."],"places":[["Hyderabad","TG",78.49,17.39,"City reference; temple celebrations occur at multiple locations."]],"sources":[["Incredible India: Telangana Bonalu","https://www.incredibleindia.gov.in/en/festivals-and-events/telangana/bonalu"]],"reviewed":"2026-10-11","photo":null,"destinationIds":["hyderabad"]},{"name":"Kharchi Puja","season":"June–July","months":[6,7],"theme":"Devotion & fair","place":"Old Agartala","description":"The Fourteen Gods are honoured through rituals and a public fair at the Chaturdasha Devata temple.","id":"kharchi-puja","states":["TR"],"regions":["Northeast"],"locations":[{"state":"TR","text":"Old Agartala"}],"native":"","categories":["Devotion","Community"],"story":"Kharchi Puja is one of Tripura’s major religious festivals, centred on the Fourteen Gods temple at Old Agartala. Its traditions connect the state’s historic royal worship with a much wider gathering of devotees and visitors. Ceremonies and a surrounding fair bring different communities together over several days. For a visitor, the temple observance and the public fair are related but distinct spaces: worshippers take priority around sacred objects and ritual routes. The lunar calendar and local organisers determine the programme each year.","rituals":["Worship associated with the fourteen deities","Ceremonial activities led by the temple’s religious authorities","A public fair and community gathering around the festival"],"food":"Sweets and other offerings have devotional roles. Food sold at the fair is a separate visitor choice; ask about ingredients and serving arrangements.","dress":"Respectful clothing suitable for temple surroundings is appropriate. Follow instructions about footwear and restricted areas.","tips":["Confirm the current temple and fair timetable before travelling from central Agartala.","Ask before photographing rituals and allow extra time for queues near the shrine."],"places":[["Old Agartala","TR",91.37,23.86,"Approximate locality near the Fourteen Gods temple; confirm the entrance locally."]],"sources":[["Tripura Information and Cultural Affairs: Kharchi Festival","https://ica.tripura.gov.in/kharchi-festival"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Garia Puja","season":"April","months":[4],"theme":"Agriculture & wellbeing","place":"Tripuri communities","description":"Traditional prayers and community celebrations seek wellbeing and a prosperous agricultural season.","id":"garia-puja","states":["TR"],"regions":["Northeast"],"locations":[{"state":"TR","text":"Tripuri communities"}],"native":"","categories":["Devotion","Harvest","Community"],"story":"Garia Puja is a spring observance among indigenous communities of Tripura, centred on prayers for well-being and prosperity. Ritual offerings and community celebration are important, but practices belong to particular communities and hosts rather than to a single statewide tourist performance. The Department of Information and Cultural Affairs documents a range of ritual ingredients, showing how material offerings form part of the observance. Visitors should seek a public programme or an invitation from a local host who can explain the significance of what is taking place.","rituals":["Community worship and offerings associated with Garia","Gatherings that express hopes for prosperity and welfare","Music and dance where included in local cultural programmes"],"food":"Ritual offerings can include rice, eggs and other items, according to local custom. They should not be treated as a standard visitor meal.","dress":"Community-specific woven dress may feature in celebrations. Ask before wearing ceremonial garments or borrowing accessories.","tips":["Use a local cultural host to identify a gathering that welcomes visitors.","Do not handle ritual objects or offerings; ask the host about any restrictions before taking photographs."],"places":[["Agartala","TR",91.29,23.83,"Planning base for community-led events; not a guaranteed ritual venue."]],"sources":[["Tripura Information and Cultural Affairs: Garia Puja","https://ica.tripura.gov.in/garia-puja"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Holi","season":"February–March","months":[2,3],"theme":"Spring & colour","place":"Mathura & Vrindavan","description":"The Braj region’s distinctive celebrations combine devotional singing and colourful traditions over several days.","id":"holi","states":["UP","RJ","BR","MP","DL"],"regions":["North","West","East","Central"],"locations":[{"state":"UP","text":"Mathura & Vrindavan"}],"native":"होली","categories":["Community","Devotion","Arts"],"story":"Holi celebrates spring through colour, gathering and stories of renewal. In the Braj region, celebrations are connected with Krishna traditions. Different towns hold distinct events on different days around the main festival.","rituals":["Holika Dahan bonfires in many communities","Colour celebrations","Devotional singing and regional performances"],"food":"Gujiya is a familiar festive sweet in northern India; local menus vary.","dress":"Choose comfortable clothes that can be stained. Clothing is not consent to participate.","tips":["Ask before applying colour or photographing participants.","Select an organised event if you prefer clear boundaries and facilities."],"places":[["Mathura","UP",77.67,27.49,"Braj devotional and colour traditions."],["Vrindavan","UP",77.7,27.58,"Temple programmes require their own date and access checks."]],"sources":[["Incredible India: Holi","https://www.incredibleindia.gov.in/en/festivals-and-events/holi"]],"photo":{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/HOLI_FESTIVAL.jpg/960px-HOLI_FESTIVAL.jpg","alt":"Person celebrating Holi amid a cloud of bright pink powder","caption":"Holi celebration in India, March 2016. Historical photograph.","author":"NIMESH DUSRA","source":"https://commons.wikimedia.org/wiki/File:HOLI_FESTIVAL.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},"reviewed":"2026-10-10","destinationIds":["mathura"]},{"name":"Dev Deepawali","season":"November; sometimes October","months":[10,11],"theme":"Festival of lamps","place":"Varanasi","description":"On Kartik Purnima, thousands of lamps illuminate the Ganges ghats in a spectacular riverside celebration.","id":"dev-deepawali","states":["UP"],"regions":["North"],"locations":[{"state":"UP","text":"Varanasi"}],"native":"","categories":["Devotion","Arts"],"story":"Dev Deepawali transforms Varanasi’s riverfront with rows of lamps on Kartik Purnima. It is a separate observance from the main Diwali night, with worship, prayers and cultural activity focused on the Ganga and its ghats. The illuminated steps are visually striking, but they remain working public and sacred spaces. A riverside walk, a fixed viewing point and a boat trip offer very different experiences; choose one that suits your group’s mobility and comfort with crowds. The exact event programme and access arrangements change by edition.","rituals":["Lighting lamps along the ghats","Prayers and riverfront religious observances","Cultural music and performances where scheduled"],"food":"Varanasi’s local snacks and sweets can be explored away from the busiest viewing areas. Festival offerings should be handled only as directed by organisers.","dress":"Wear comfortable shoes with grip for steps and respectful clothing around worship areas. Carry a light evening layer.","tips":["Identify your return route before the ghats become crowded.","For boat viewing, confirm boarding location, capacity and life-jacket provision directly with the operator."],"places":[["Varanasi","UP",83,25.32,"City reference; choose and confirm a particular ghat or boarding point."]],"sources":[["Kashi Government Portal: Dev Deepawali","https://kashi.gov.in/event/dev-deepawali"],["Incredible India: Dev Deepawali","https://www.incredibleindia.gov.in/en/festivals-and-events/uttar-pradesh/illuminating-the-eternal-spirit-of-kashi"]],"reviewed":"2026-10-11","photo":null,"destinationIds":["varanasi"]},{"name":"Harela","season":"July","months":[7],"theme":"Monsoon & nature","place":"Kumaon","description":"Seedlings grown in the days before the festival symbolise greenery, prosperity and the agricultural season.","id":"harela","states":["UT"],"regions":["North"],"locations":[{"state":"UT","text":"Kumaon"}],"native":"हरेला","categories":["Harvest","Community"],"story":"Harela celebrates greenery and the close relationship between people and the agricultural landscape of Uttarakhand. The monsoon observance is especially associated with Kumaon, while contemporary celebrations across the state include tree planting and environmental activities. The festival offers a useful introduction to living local traditions beyond the better-known pilgrimage routes. A household ceremony, village gathering and organised plantation event may each emphasise different aspects. Visitors interested in joining should choose a publicly announced activity and learn from the organisers about its local meaning.","rituals":["Seasonal celebrations connected with greenery and agriculture","Family or community observances according to local custom","Tree-planting programmes organised by community and public bodies"],"food":"Meals depend on the household or event. Try regional Kumaoni food through a local host, without assuming that one dish defines every Harela celebration.","dress":"Comfortable clothing suitable for outdoor activity is useful. For planting programmes, use footwear that can cope with mud.","tips":["Check the local programme and weather before travelling to an outdoor activity.","Join planting only through organisers who select appropriate species and arrange ongoing care."],"places":[["Almora","UT",79.66,29.6,"Kumaon town reference; confirm a public local programme."]],"sources":[["Uttarakhand Governor: Harela celebration","https://governoruk.gov.in/16-07-2024harela-the-festival-that-signifies-uttarakhands-folk-culture-and-environmental-conservation-was-celebrated-at-raj-bhawan/"],["Uttarakhand Chief Electoral Officer: Harela","https://ceo.uk.gov.in/event/harela-festival-2025/"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Phool Dei","season":"March","months":[3],"theme":"Spring","place":"Garhwal & Kumaon","description":"Children place flowers at doorsteps to welcome spring and offer blessings for the household.","id":"phool-dei","states":["UT"],"regions":["North"],"locations":[{"state":"UT","text":"Garhwal & Kumaon"}],"native":"फूल देई","categories":["Community","Harvest"],"story":"Phool Dei welcomes spring in Uttarakhand through a gentle tradition closely associated with children. Flowers are placed at household thresholds with wishes for happiness and prosperity, linking neighbourhood life with the changing season. Cultural organisations also arrange public celebrations to help younger generations learn the songs and customs. It is principally a community practice rather than a large destination festival. A host-led visit offers a better understanding than searching for a single central venue, and visitors should respect the privacy of homes and participating families.","rituals":["Children placing flowers at thresholds","Good wishes and seasonal songs","Community activities that pass traditions between generations"],"food":"Households may share small treats with participating children; offerings and recipes vary. Ask parents before giving children any food.","dress":"Everyday or locally chosen festive dress is appropriate; practical footwear helps when moving between homes.","tips":["Seek a public cultural event or a host’s invitation rather than following children into private homes.","Ask parental permission before photographing children and use flowers obtained without damaging wild plants."],"places":[["Almora","UT",79.66,29.6,"Town reference for local spring traditions; public venues vary."]],"sources":[["Uttarakhand Governor: Phool Dei traditions","https://governoruk.gov.in/14-03-2021-lokphar-phuldei-is-a-celebration-of-environmental-protection-governor/"],["Uttarakhand Tourism: Voices and culture","https://www.uttarakhandtourism.gov.in/page/voices-and-culture"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Durga Puja","season":"September–October","months":[9,10],"theme":"Art, devotion & community","place":"Kolkata & across West Bengal","description":"Neighbourhoods become open-air galleries of elaborate pandals and Durga idols. Dhak drums, dhunuchi dance and shared bhog bring people together in a celebration of creativity and devotion.","id":"durga-puja","states":["WB","OR","TR","AS"],"regions":["East","Northeast"],"locations":[{"state":"WB","text":"Kolkata & across West Bengal"}],"native":"দুর্গাপূজা","categories":["Devotion","Arts","Community"],"story":"Durga Puja honours the goddess Durga and her victory over Mahishasura. In Bengal, it is also imagined as a daughter's homecoming. Kolkata's neighbourhood pandals make the celebration a meeting of public art, craftsmanship and worship.","rituals":["Pandal visits and viewing crafted idols","Dhak drumming, prayers and dhunuchi dance","Immersion processions at the close of the observance"],"food":"Shared bhog often includes khichuri; sweets and family meals are part of the wider celebrations.","dress":"Saris, kurtas and everyday festive clothing; red-and-white combinations are a familiar sight, not a visitor requirement.","tips":["Ask before photographing worship or individuals.","Visit earlier in the day for a gentler introduction; evening queues can be long."],"places":[["Kolkata","WB",88.36,22.57,"Neighbourhood pandals and public art; individual opening times vary."]],"sources":[["Incredible India: Durga Puja","https://www.incredibleindia.gov.in/en/festivals-and-events/durga-puja"]],"photo":{"url":"https://upload.wikimedia.org/wikipedia/commons/0/05/Durga_Puja_in_West_Bengal.jpg","alt":"Durga idol and accompanying figures inside an illuminated pandal in West Bengal","caption":"Durga Puja in West Bengal, 2022. Historical photograph; not a preview of the current year's event.","author":"Prantik006","source":"https://commons.wikimedia.org/wiki/File:Durga_Puja_in_West_Bengal.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},"reviewed":"2026-10-10","destinationIds":["kolkata"]},{"name":"Kali Puja","season":"October–November","months":[10,11],"theme":"Devotion & light","place":"Kolkata & across West Bengal","description":"Homes and temples honour Goddess Kali with lamps, offerings and evening worship around the new moon.","id":"kali-puja","states":["WB"],"regions":["East"],"locations":[{"state":"WB","text":"Kolkata & across West Bengal"}],"native":"কালীপূজা","categories":["Devotion","Arts","Community"],"story":"Kali Puja honours the goddess Kali and is particularly prominent in West Bengal. Temples, household shrines and neighbourhood pandals each create their own setting for worship, often with elaborate images and lighting. The observance falls around the autumn new moon associated with Diwali, but its devotional focus is distinct. Kolkata offers both major temple traditions and community celebrations; a carefully chosen neighbourhood route is more practical than trying to see everything in one night. Ritual timing and visitor access should be checked with each venue.","rituals":["Worship of Kali at temples and household or community shrines","Decorated pandals and goddess images","Evening lighting and neighbourhood gatherings"],"food":"Prasad and meals vary widely by temple and community. Ask organisers what is available and avoid assuming that every venue serves the same offerings.","dress":"Festive clothing is common, while visitors should choose respectful dress and comfortable shoes for queues and walking.","tips":["Check whether photography is permitted inside a temple or pandal.","Keep routes short enough for your group, and arrange a meeting point away from the busiest entrance."],"places":[["Kolkata","WB",88.36,22.57,"City reference; temple and neighbourhood pandal locations differ."]],"sources":[["Incredible India: Kali Puja","https://www.incredibleindia.gov.in/en/festivals-and-events/kali-puja"]],"reviewed":"2026-10-11","photo":null,"destinationIds":["kolkata"]},{"name":"Poila Boishakh","season":"April","months":[4],"theme":"Bengali New Year","place":"Across West Bengal","description":"New account books, cultural programmes and generous Bengali meals mark the start of the Bengali year.","id":"poila-boishakh","states":["WB"],"regions":["East"],"locations":[{"state":"WB","text":"Across West Bengal"}],"native":"পয়লা বৈশাখ","categories":["Community","Arts"],"story":"Poila Boishakh marks the beginning of the Bengali calendar year. In West Bengal, it brings together family meals, new clothes, greetings and cultural programmes. Some businesses observe Halkhata, the symbolic opening of a new accounts ledger, often welcoming customers with sweets. Music, neighbourhood activity and household traditions give the occasion a character that extends beyond a single religious setting. Kolkata is a useful base, though celebrations also take place across Bengali communities. Follow the local calendar rather than assuming every country or community observes an identical date.","rituals":["New Year greetings and family gatherings","Halkhata customs among participating businesses","Music, cultural programmes and household alpana designs"],"food":"Bengali sweets and festive meals are prominent, but menus vary by household and restaurant. Book a special restaurant meal directly if that is your preferred experience.","dress":"Saris, kurtas and other new festive clothing are common choices; there is no required visitor costume.","tips":["Choose an announced cultural programme for public participation.","Ask a shopkeeper before photographing a Halkhata ceremony; it is a business and devotional custom, not a staged attraction."],"places":[["Kolkata","WB",88.36,22.57,"City reference for Bengali New Year cultural programmes."]],"sources":[["West Bengal Tourism official blog: Poila Boishakh","https://wbtourismdotblog.wordpress.com/2019/04/16/poila-boishakh-the-changing-face-of-bengali-new-year-celebration/"]],"reviewed":"2026-10-11","photo":null,"destinationIds":["kolkata"]},{"name":"Island Tourism Festival","season":"Schedule varies","months":[],"theme":"Cultural showcase","place":"Sri Vijaya Puram (Port Blair)","description":"A public cultural programme showcases island communities through performances, exhibitions and local food; confirm the organiser’s current schedule.","id":"island-tourism-festival","states":["AN"],"regions":["Islands"],"locations":[{"state":"AN","text":"Sri Vijaya Puram (Port Blair)"}],"native":"","categories":["Arts","Community"],"story":"The Island Tourism Festival is an organised cultural event in the Andaman and Nicobar Islands. It brings together performances, exhibitions and public entertainment, with visiting mainland troupes joining island-based cultural groups. This makes it different from a single community’s religious festival: its programme is curated by the organisers and can change from one edition to another. The principal urban venue has historically been the ITF Ground in the capital, now named Sri Vijaya Puram. Use the current official announcement to establish dates and venues rather than relying on the festival’s historic January pattern.","rituals":["Stage programmes featuring music and dance","Exhibitions and stalls where included in the edition","Participation by island and visiting cultural groups"],"food":"Food stalls depend on the published programme. Ask vendors about seafood, allergens and vegetarian choices; the event does not have one prescribed festival meal.","dress":"Light everyday clothing and comfortable footwear suit outdoor stalls; performers wear the clothing appropriate to their own traditions.","tips":["Confirm the current edition and exact ground before planning travel around the festival.","Treat cultural performances as specific to their participating communities rather than representative of every island community."],"places":[["Sri Vijaya Puram","AN",92.74,11.67,"Capital city reference; verify the ITF Ground entrance and any additional venues."]],"sources":[["Ministry of Tourism: Island Tourism Festival","https://www.utsav.gov.in/view-event/island-tourism-festival-1"],["Andaman and Nicobar Directorate of Art and Culture","https://artculture.andamannicobar.gov.in/"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Rose Festival","season":"February–March","months":[2,3],"theme":"Flowers & culture","place":"Zakir Hussain Rose Garden","description":"Flower displays and cultural activities celebrate the city’s garden heritage.","id":"rose-festival","states":["CH"],"regions":["North"],"locations":[{"state":"CH","text":"Zakir Hussain Rose Garden"}],"native":"","categories":["Arts","Community"],"story":"Chandigarh’s Rose Festival is an organised civic celebration built around the city’s rose gardens and seasonal blooms. It combines horticultural interest with a public festival atmosphere, and the tourism administration usually places it in the late-February period. Visitors can approach it as a garden outing, while any entertainment, competitions or additional attractions depend on that edition’s programme. The Rose Garden is the main geographical reference, but organisers may use surrounding public spaces as well. Confirm the official announcement before assuming a particular activity or opening time.","rituals":["Viewing rose displays and garden plantings","Public cultural activities where announced","Horticultural interest and community participation"],"food":"Refreshments depend on approved stalls and nearby businesses. There is no ritual menu; bring drinking water and ask about ingredients at food counters.","dress":"Comfortable daytime clothing and walking shoes work well. A light layer may be useful for an evening programme.","tips":["Stay on permitted paths and leave flowers for everyone to enjoy.","Check the festival’s current programme, access points and transport arrangements rather than relying on a previous year’s listing."],"places":[["Chandigarh","CH",76.79,30.74,"City centre reference near the Rose Garden; confirm the current festival access points."]],"sources":[["Ministry of Tourism: Chandigarh Rose Festival","https://utsav.gov.in/view-event/chandigarh-rose-festival"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Nariyal Purnima","season":"August","months":[8],"theme":"Coastal tradition","place":"Coastal communities of Daman & Diu","description":"Fishing communities offer coconuts to the sea, accompanied by prayers and local celebrations.","id":"nariyal-purnima","states":["DH"],"regions":["West"],"locations":[{"state":"DH","text":"Coastal communities of Daman & Diu"}],"native":"","categories":["Devotion","Community"],"story":"Nariyal Purnima, also known as Narali Purnima in neighbouring coastal traditions, is associated with coconut offerings and respect for the sea. Daman is one of the places where the festival forms part of local coastal cultural life. Related fishing-community observances express hopes for protection and a fruitful season, while organised cultural activities can add a public element. The ceremonial occasion should not be interpreted as a guarantee of safe sea conditions or a universal date for fishing to resume. Local weather, rules and community arrangements still govern activity on the water.","rituals":["Coconut offerings associated with devotion to the sea","Community gatherings in coastal settings","Cultural programmes where locally announced"],"food":"Coconut features symbolically in the festival. Nearby vendors may offer local snacks; ceremonial offerings should not be taken without guidance.","dress":"Light, respectful clothing and footwear suitable for the waterfront are practical. Community participants may wear festive regional dress.","tips":["Confirm the local gathering place with organisers before travelling to the waterfront.","Stay behind waterfront barriers and avoid adding packaging or other litter to the sea."],"places":[["Daman","DH",72.83,20.42,"Coastal town reference; verify the designated celebration area."]],"sources":[["Incredible India: Daman","https://www.incredibleindia.gov.in/en/dadra-and-nagar-haveli-and-daman-and-diu/daman"],["Ministry of Tourism: Narali Purnima","https://utsav.gov.in/view-event/narali-purnima"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Diwali","season":"October–November","months":[10,11],"theme":"Festival of lights","place":"Across Delhi","description":"Diyas, family gatherings, sweets and worship mark the festival of lights in the capital.","id":"diwali","states":["DL","UP","RJ","MH","GJ","KA","TN"],"regions":["North","West","South"],"locations":[{"state":"DL","text":"Across Delhi"}],"native":"दीपावली","categories":["Devotion","Community"],"story":"Diwali, or Deepavali, is a festival of lights celebrated through many regional and community traditions. Lamps, decorated homes, sweets and family gatherings are familiar features, but the stories and ceremonies are not identical everywhere. Worship of Lakshmi is important in many Hindu households, while other communities give the season their own meanings. Public illuminations and markets offer visitors a way to experience the atmosphere without needing access to a private home. Choose a destination and local programme first: the surrounding festive days matter as much as the main night.","rituals":["Lighting diyas and decorating homes or public spaces","Family worship and gatherings according to local tradition","Exchanging sweets, greetings and gifts"],"food":"Mithai and savoury snacks are widely shared; recipes differ across India. Nuts, milk and ghee are common, so ask about ingredients.","dress":"Festive clothing is common. Keep loose fabrics away from oil lamps and choose practical footwear for crowded markets.","tips":["Confirm local public events and transport arrangements before choosing a viewing route.","Accept household invitations respectfully and ask before photographing a family’s worship."],"places":[["Delhi","DL",77.21,28.61,"City reference for markets and public celebrations; choose a specific local programme."]],"sources":[["Incredible India: Diwali","https://www.incredibleindia.gov.in/en/festivals-and-events/diwali"]],"reviewed":"2026-10-11","photo":{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/Diwali_Diyas_Lamps.jpg/960px-Diwali_Diyas_Lamps.jpg","alt":"Lit clay diyas arranged around a decorated lamp during Diwali","caption":"Diwali lamps, October 2011. Historical photograph.","author":"humdingor","source":"https://commons.wikimedia.org/wiki/File:Diwali_Diyas_Lamps.jpg","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0/"},"destinationIds":[]},{"name":"Eid al-Fitr","season":"Moves through the solar year","months":[],"theme":"Community & faith","place":"Old Delhi & across the city","description":"Prayers, charitable giving and festive meals mark the end of Ramadan; dates depend on the lunar calendar.","id":"eid-al-fitr","states":["DL","JK","LD"],"regions":["North","Islands"],"locations":[{"state":"DL","text":"Old Delhi & across the city"},{"state":"JK","text":"Srinagar & across the territory"},{"state":"LD","text":"Across the islands"}],"native":"","categories":["Devotion","Community"],"story":"Eid al-Fitr marks the completion of Ramadan, bringing Muslim communities together in prayer, generosity and celebration. Family visits, greetings and shared meals are central to many households, alongside care for people in need. The occasion is observed across India, with distinct local food and cultural traditions rather than a single standard celebration. Its date follows the Islamic calendar and local moon-sighting announcements, so a forecast date should not be presented as confirmed. In Delhi, the neighbourhoods around major mosques can be lively, but worship spaces remain places of prayer.","rituals":["Congregational Eid prayer","Charitable giving and support for others","Family visits, greetings and shared festive meals"],"food":"Sweet vermicelli preparations and other festive foods vary by region and family. Check ingredients and opening times with individual restaurants.","dress":"Worshippers often wear their best or new clothes. Visitors entering a mosque should follow its requirements for modest dress and footwear.","tips":["Confirm the locally announced date and visitor access directly with the mosque.","Do not obstruct prayer or photograph worshippers without permission; explore surrounding markets at a suitable time."],"places":[["Delhi","DL",77.21,28.61,"City reference; confirm access and prayer arrangements at individual mosques."]],"sources":[["Incredible India: Eid ul-Fitr","https://www.incredibleindia.gov.in/en/festivals-and-events/eid-ul-fitr"],["Delhi Tourism: Eid-ul-Fitr","https://delhitourism.gov.in/dt/festivals/eid-ul-fitr.html"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Herath","season":"February–March","months":[2,3],"theme":"Kashmiri Pandit tradition","place":"Kashmiri Pandit communities","description":"The Kashmiri observance of Shivratri centres on family worship, ritual offerings and festive food.","id":"herath","states":["JK"],"regions":["North"],"locations":[{"state":"JK","text":"Kashmiri Pandit communities"}],"native":"","categories":["Devotion","Community"],"story":"Herath is the Kashmiri Pandit observance of Shivaratri, with a distinctive sequence of household preparations, worship and social visits. The Indira Gandhi National Centre for the Arts documents the use of ritual vessels and walnuts in the ceremonies, followed by the sharing of soaked walnuts with relatives, friends and neighbours. It is primarily a living family and community tradition, not a single public spectacle. Kashmiri Pandit communities also maintain the celebration beyond the Kashmir Valley, so its cultural geography extends beyond any one destination.","rituals":["Household worship involving ritual vessels","Preparation and later sharing of soaked walnuts","Visits and exchanges that renew family and neighbourhood ties"],"food":"Walnuts have a specific ceremonial role. Other dishes vary by household, and a visitor should ask their host about the meal rather than assume one Shivaratri menu applies everywhere.","dress":"Respectful everyday or festive clothing is suitable when invited. Warm layers are useful for a winter visit to Srinagar.","tips":["Join a household observance only by invitation and follow the host’s guidance around sacred vessels.","Confirm any public temple programme separately; it may not reflect the full sequence of home rituals."],"places":[["Srinagar","JK",74.8,34.08,"City reference for Kashmiri Pandit heritage; household ceremonies are private."]],"sources":[["Indira Gandhi National Centre for the Arts: Mahasivaratri in Kashmir","https://ignca.gov.in/mahasivaratri-in-kashmir/"]],"reviewed":"2026-10-11","photo":null,"destinationIds":[]},{"name":"Hemis Festival","season":"June–July","months":[6,7],"theme":"Monastic tradition","place":"Hemis Monastery","description":"Masked cham dances and monastery rituals commemorate Guru Padmasambhava.","id":"hemis-festival","states":["LA"],"regions":["North"],"locations":[{"state":"LA","text":"Hemis Monastery"}],"native":"Hemis Tsechu","categories":["Devotion","Music & dance","Arts"],"story":"Hemis Festival honours Guru Padmasambhava at Hemis Monastery in Ladakh. Its cham dances are religious performances, not simply entertainment. The annual dates follow the Tibetan lunar calendar.","rituals":["Masked cham dances","Monastery prayers","Ceremonial music"],"food":"Explore local Ladakhi food outside the ritual spaces; follow monastery rules on eating.","dress":"Modest layers suit monastery visits and changeable mountain conditions.","tips":["Ask before photographing religious performances or interiors.","Confirm seating and step-free access with the monastery or organiser."],"places":[["Hemis Monastery","LA",77.7,33.91,"Monastery courtyard; visitor arrangements depend on the programme."]],"sources":[["Incredible India: Hemis","https://www.incredibleindia.gov.in/en/rural-tourism/hemis"]],"photo":null,"reviewed":"2026-10-10","destinationIds":[]}],"events":[{"id":"holi-2026","festival":"holi","year":2026,"start":"2026-03-04","end":"2026-03-04","status":"Published listing","place":"India-wide observance; local Braj events vary","source":"https://www.incredibleindia.gov.in/en/plan-your-trip/public-holidays","note":"Main holiday date, not the full Braj programme.","checked":"2026-10-10","states":["UP"],"nationwide":true},{"id":"ganesh-2026","festival":"ganesh-chaturthi","year":2026,"start":"2026-09-14","end":"2026-09-14","status":"Published listing","place":"Maharashtra and other regions","source":"https://www.incredibleindia.gov.in/en/festivals-and-events/maharashtra/ganesh-chaturthi","note":"Opening observance only. Household durations and immersion dates vary.","checked":"2026-10-10","states":["MH"],"nationwide":false},{"id":"navratri-2026","festival":"navratri","year":2026,"start":"2026-10-11","end":"2026-10-19","status":"Published listing","place":"Gujarat and other regions","source":"https://www.incredibleindia.gov.in/en/festivals-and-events/navratri","note":"Autumn Navratri listing. Individual garba venues set their own schedules and tickets.","checked":"2026-10-10","states":["GJ"],"nationwide":false},{"id":"mysuru-2026","festival":"mysuru-dasara","year":2026,"start":"2026-10-11","end":"2026-10-21","status":"Provisional","place":"Mysuru, Karnataka","source":"https://www.incredibleindia.gov.in/en/festivals-and-events/mysuru-dasara","note":"Tourism listing extends to 21 October; it is not a confirmed procession date. Verify the local programme before booking.","checked":"2026-10-10","states":["KA"],"nationwide":false},{"id":"durga-2026","festival":"durga-puja","year":2026,"start":"2026-10-17","end":"2026-10-21","status":"Provisional","place":"Kolkata, West Bengal","source":"https://www.incredibleindia.gov.in/en/festivals-and-events/durga-puja","note":"Tourism listing shows 17–21 October; local ritual calendars may differ. Verify with the pandal organiser.","checked":"2026-10-10","states":["WB"],"nationwide":false},{"id":"diwali-2026","festival":"diwali","year":2026,"start":"2026-11-08","end":"2026-11-08","status":"Published listing","place":"Across India; regional observances vary","source":"https://www.incredibleindia.gov.in/en/festivals-and-events/diwali","note":"Main listed observance, not every regional or multiday celebration.","checked":"2026-10-10","states":[],"nationwide":true},{"id":"chhath-2026","festival":"chhath-puja","year":2026,"start":"2026-11-13","end":"2026-11-16","status":"Published listing","place":"Bihar and participating communities","source":"https://www.incredibleindia.gov.in/en/bihar","note":"Four-day tourism listing; local ghat access and ritual timings require separate confirmation.","checked":"2026-10-10","states":["BR"],"nationwide":false},{"id":"hornbill-2026","festival":"hornbill-festival","year":2026,"start":"2026-12-01","end":"2026-12-10","status":"Published listing","place":"Kisama, near Kohima, Nagaland","states":["NL"],"nationwide":false,"source":"https://tourism.nagaland.gov.in/","note":"State tourism lists these dates. Check daily programmes, entry arrangements and any changes with organisers.","checked":"2026-10-12"},{"id":"pushkar-2026","festival":"pushkar-fair","year":2026,"start":"2026-11-17","end":"2026-11-24","status":"Published listing","place":"Pushkar, Rajasthan","states":["RJ"],"nationwide":false,"source":"https://www.incredibleindia.gov.in/en/festivals-and-events/pushkar-camel-fair","note":"Tourism-listed fair window; livestock trading and religious observances may have different schedules.","checked":"2026-10-12"},{"id":"sonepur-2026","festival":"sonepur-mela","year":2026,"start":"2026-11-24","end":"2026-12-05","status":"Provisional","place":"Sonepur, Bihar","states":["BR"],"nationwide":false,"source":"https://www.incredibleindia.gov.in/en/festivals-and-events/sonepur-cattle-fair","note":"The date field lists 24 November–5 December, while the page describes a month-long fair. Confirm the actual duration and programme with Bihar Tourism.","checked":"2026-10-12"},{"id":"dev-varanasi-2026","festival":"dev-deepawali","year":2026,"start":"2026-11-24","end":"2026-11-24","status":"Provisional","place":"Varanasi, Uttar Pradesh","states":["UP"],"nationwide":false,"source":"https://www.incredibleindia.gov.in/en/festivals-and-events/uttar-pradesh/illuminating-the-eternal-spirit-of-kashi","note":"The detail page lists 24 November; the directory spans 24–25 November. Confirm the principal illumination night and access arrangements.","checked":"2026-10-12","title":"Dev Deepawali — Varanasi"},{"id":"dev-prayagraj-2026","festival":"dev-deepawali","year":2026,"start":"2026-11-24","end":"2026-11-24","status":"Published listing","place":"Prayagraj, Uttar Pradesh","states":["UP"],"nationwide":false,"source":"https://www.incredibleindia.gov.in/en/festivals-and-events/uttar-pradesh/dev-deepawali-prayagraj","note":"City-specific listing. Confirm ghat access and timings with the local organiser.","checked":"2026-10-12","title":"Dev Deepawali — Prayagraj"},{"id":"khajuraho-2027","festival":"khajuraho-dance-festival","year":2027,"start":"2027-02-20","end":"2027-02-26","status":"Provisional","place":"Khajuraho Group of Temples, Madhya Pradesh","states":["MP"],"nationwide":false,"source":"https://www.mptourism.com/khajuraho-dance-festival.htm","note":"The title and date field specify 2027, but the introductory paragraph says 2026. Treat this as provisional until the organiser resolves the mismatch.","checked":"2026-10-12"},{"id":"sankranti-sidhi-2027","festival":"sankranti","year":2027,"start":"2027-01-14","end":"2027-01-15","status":"Published listing","place":"Jogdaha Ghat, Sidhi, Madhya Pradesh","states":["MP"],"nationwide":false,"source":"https://www.incredibleindia.gov.in/en/festivals-and-events/madhya-pradesh/makar-sankranti-fair","note":"Dates apply to this local fair, not every regional Sankranti observance. Confirm venue access and the daily programme.","checked":"2026-10-12","title":"Makar Sankranti Fair — Sidhi"},{"id":"sankranti-kites-2027","festival":"sankranti","year":2027,"start":"2027-01-13","end":"2027-01-15","status":"Published listing","place":"Parade Grounds, Secunderabad, Telangana","states":["TG"],"nationwide":false,"source":"https://www.incredibleindia.gov.in/en/festivals-and-events/telangana/international-kite---sweet-festival","note":"A tourism programme associated with Sankranti. These dates describe the kite and sweet festival, not the religious observance throughout India.","checked":"2026-10-12","title":"International Kite & Sweet Festival — Hyderabad"},{"id":"kite-ahmedabad-2027","festival":"uttarayan","title":"International Kite Festival — Ahmedabad","year":2027,"start":"2027-01-10","end":"2027-01-14","states":["GJ"],"nationwide":false,"place":"Sabarmati Riverfront, Ahmedabad","source":"https://www.incredibleindia.gov.in/en/festivals-and-events/gujarat/International-Kite-Festival0","status":"Provisional","note":"The national tourism listing gives these 2027 dates; the organiser microsite still describes the 2026 edition. Confirm the 2027 programme before booking.","checked":"2026-10-13"},{"id":"braj-bharatpur-2027","festival":"holi","title":"Braj Holi Festival — Bharatpur","year":2027,"start":"2027-03-17","end":"2027-03-18","states":["RJ"],"nationwide":false,"place":"Bharatpur, Rajasthan","source":"https://www.incredibleindia.gov.in/en/festivals-and-events/rajasthan/braj-holi-festival","status":"Published listing","note":"Dates for the local Bharatpur cultural programme, not all Holi celebrations across Braj. Check the final programme with Rajasthan Tourism.","checked":"2026-10-13"},{"id":"dhulandi-jaipur-2027","festival":"holi","title":"Dhulandi Festival — Jaipur","year":2027,"start":"2027-03-22","end":"2027-03-22","states":["RJ"],"nationwide":false,"place":"Khasa Kothi, Jaipur","source":"https://www.incredibleindia.gov.in/en/festivals-and-events/rajasthan/dhulandi-festival","status":"Published listing","note":"Local Rajasthan Tourism programme. Confirm admission arrangements and participation requirements with the organiser.","checked":"2026-10-13"},{"id":"rangotsav-braj-2027","festival":"holi","title":"Rangotsav — Mathura and Vrindavan","year":2027,"start":"2027-03-16","end":"2027-03-30","states":["UP"],"nationwide":false,"place":"Mathura and Vrindavan, Uttar Pradesh","source":"https://www.incredibleindia.gov.in/en/festivals-and-events/uttar-pradesh/rangotsav-2027","status":"Published listing","note":"Broad regional programme window published by UP Tourism. Individual temple rituals and local celebrations have separate schedules.","checked":"2026-10-13"},{"id":"rangpanchami-indore-2027","festival":"holi","title":"Rangpanchami Ger Mahotsav — Indore","year":2027,"start":"2027-03-27","end":"2027-03-27","states":["MP"],"nationwide":false,"place":"Rajwada, Indore","source":"https://www.incredibleindia.gov.in/en/festivals-and-events/madhya-pradesh/rangpanchami-ger-mahotsav0","status":"Published listing","note":"Local Rangpanchami celebration associated with the Holi season. Check procession timings and routes closer to the event.","checked":"2026-10-13"},{"id":"mewar-udaipur-2027","festival":"gangaur","title":"Mewar Festival — Udaipur and Gogunda","year":2027,"start":"2027-04-09","end":"2027-04-11","states":["RJ"],"nationwide":false,"place":"Jagdish Chowk, Gangaur Ghat, Udaipur and Gogunda","source":"https://www.incredibleindia.gov.in/en/festivals-and-events/rajasthan/mewar-festival-2026","status":"Provisional","note":"The source date field says 9–11 April 2027 but the page title and URL still say 2026. Confirm the edition and dates with the Tourist Reception Centre, Udaipur.","checked":"2026-10-13"}]};
